function card(type,o){let name=o.name,subtitle='',meta='',img='',evidence=tag('Decoded data');let key=o.id;if(type==='buildings'){key=o.gameobject_id;img=icon(type,o);subtitle=plain(o.description).slice(0,110);meta=(o.max_workers!==null?`${o.max_workers} workers`:(o.sleep_spots!==null?`${o.sleep_spots} sleep spots`:'Building reference'))+(o.variants?.length>1?` · ${o.variants.length} variants`:'')}if(type==='resources'){img=icon(type,o);subtitle=o.publicly_named?'Resource values, recipes and related buildings.':'An internal production state or resource definition.';meta=o.publicly_named?'Named game resource':'Internal intermediate'}if(type==='chains'){key=o.gameobject_id;img=icon('buildings',o);const q=cycleRecipe(o);subtitle=q?q.inputs.map(x=>`${fmt(x.count)} ${x.name}`).join(' + ')+' → '+q.outputs.map(x=>`${fmt(x.count)} ${x.name}`).join(' + '):'Explore the individual steps, inputs and outputs.';meta=`${o.formula_ids.length} formula steps`;evidence=tag('Derived from data')}if(type==='heroes'){img=icon(type,o);subtitle=plain(o.effect);meta='Hero / leader';evidence=tag('Game text')}if(type==='biomes'){img=icon(type,o);subtitle=o.rules_text.length?'Environmental needs and recovered help text.':'A named biome with original game artwork.';meta=o.rules_text.length?`${o.rules_text.length} help entries`:'Rules still being documented';evidence=tag('Game text')}if(type==='levels'){img=`<span class="placeholder-icon">⚑</span>`;subtitle=plain(o.description).slice(0,140);meta=o.category==='campaign'?`Campaign ${o.campaign_number}`:o.category==='tutorial'?'Tournament tutorial':'Map category unverified';evidence=tag('Objective templates')}return `<a class="card" href="${url(type,key)}"><div class="card-image ${type==='heroes'?'portrait':type==='biomes'?'landscape':''}">${img}</div><div class="card-body"><div>${evidence}</div><h3 style="margin-top:9px">${esc(name)}</h3><p>${esc(subtitle)}</p><div class="card-meta"><span>${esc(meta)}</span><span>↗</span></div></div></a>`}
