// Readable recipes for buildings whose stored step graph has alternatives, fuel multipliers, returned containers or self-made starts (issue 47).
function recipeGraph(b){const fs=b.formula_ids.map(i=>F[i]).filter(Boolean);if(!fs.length)return [];const producers=new Map();for(const f of fs)for(const o of f.outputs){if(!producers.has(o.resource_id))producers.set(o.resource_id,[]);producers.get(o.resource_id).push(f)}const consumed=new Set(fs.flatMap(f=>f.inputs.map(x=>x.resource_id)));const finals=uniq(fs.flatMap(f=>f.outputs.map(o=>R[o.resource_id])).filter(r=>r&&r.publicly_named&&!consumed.has(r.id)),r=>r.id);
 const expand=(rid,amount,depth)=>{const r=R[rid];const prods=producers.get(rid)||[];if(depth>12)return {leaves:[],notes:['loop']};
  if(!prods.length){if(r?.publicly_named)return {leaves:[{kind:'input',r,amount}],notes:[]};return {leaves:[{kind:'container',r,amount}],notes:[]}}
  const branches=prods.map(f=>{const c=f.outputs.find(o=>o.resource_id===rid)?.count||1;const runs=amount/c;const leaves=[],notes=[];if(!f.inputs.length){if(f.resource_source_category_ids?.length)leaves.push({kind:'source',r,amount,cat:f.resource_source_category_ids[0],self:depth===0});else leaves.push({kind:'free',r,amount})}for(const x of f.inputs){const sub=expand(x.resource_id,runs*x.count,depth+1);leaves.push(...sub.leaves);notes.push(...sub.notes)}for(const o of f.outputs)if(o.resource_id!==rid&&R[o.resource_id]?.publicly_named)notes.push(`also ${fmt(Math.round(o.count*runs*100)/100)} ${esc(R[o.resource_id].name)}`);return {leaves,notes}});
  if(branches.length===1)return branches[0];const key=br=>JSON.stringify(br.leaves.map(l=>[l.kind,l.r?.name,Math.round(l.amount*1000)]).sort());if(new Set(branches.map(key)).size===1)return branches[0];
  const simple=branches.every(br=>br.leaves.length===1&&br.leaves[0].kind==='input')&&new Set(branches.map(br=>Math.round(br.leaves[0].amount*1000))).size===1;if(simple)return {leaves:[{kind:'any',options:branches.map(br=>br.leaves[0].r),amount:branches[0].leaves[0].amount}],notes:[]};
  return {leaves:[{kind:'alt',branches,amount}],notes:[]}};
 const done=new Set();return finals.map(r=>{if(done.has(r.id))return null;const prods=producers.get(r.id);const f0=prods[0];const co=prods.length===1?f0.outputs.map(o=>R[o.resource_id]).filter(x=>x&&x.publicly_named&&finals.some(z=>z.id===x.id)):[r];for(const x of co)done.add(x.id);const c=f0.outputs.find(o=>o.resource_id===r.id)?.count||1;const {leaves,notes}=expand(r.id,c,0);return {products:co.map(x=>({r:x,count:f0.outputs.find(o=>o.resource_id===x.id)?.count||1})),leaves:mergeLeaves(leaves),notes:[...new Set(notes)].filter(n=>!co.some(x=>n.endsWith(esc(x.name))))}}).filter(Boolean)}
function mergeLeaves(leaves){const out=[];for(const l of leaves){const k=l.kind+':'+(l.r?l.r.id:l.options?l.options.map(o=>o.id).join('|'):'alt');const hit=out.find(o=>o.key===k);if(hit&&l.kind!=='alt')hit.amount+=l.amount;else out.push({key:k,...l})}return out}
function fraction(n){const r=Math.round(n*1000)/1000;if(Number.isInteger(r))return fmt(r);for(const d of [2,3,4,5,6,8,10,12,15,20]){const num=Math.round(r*d);if(Math.abs(num/d-r)<1e-6)return num>d?`${Math.floor(num/d)} ${num%d}/${d}`:`${num}/${d}`}return fmt(Math.round(r*100)/100)}
function leafText(l){const rl=r=>`<a class="resource-link" href="${url('resources',r.id)}">${esc(r.name)}</a>`;if(l.kind==='input')return `${fraction(l.amount)} ${rl(l.r)}`;if(l.kind==='any')return `${fraction(l.amount)} × (${joinNames(l.options.map(rl),'or')})`;if(l.kind==='source')return `${l.self?'':fraction(l.amount)+' '+rl(l.r)+' '}gathered from ${esc((SOURCE_CATEGORY[l.cat]||'the map').replace(/\s*\(.*\)$/,''))}`;if(l.kind==='free')return null;if(l.kind==='container')return null;if(l.kind==='alt')return `either ${l.branches.map(br=>br.leaves.map(leafText).filter(Boolean).join(' + ')).join(' or ')}`;return ''}
function readableRecipe(b){const graph=recipeGraph(b);if(!graph.length)return '';return `<ul class="recipe-steps readable-recipes">${graph.map(g=>{const inputs=g.leaves.filter(l=>l.kind!=='container'),containers=g.leaves.filter(l=>l.kind==='container');const free=g.leaves.some(l=>l.kind==='free');const lhsParts=inputs.map(leafText).filter(Boolean);if(free&&lhsParts.length)lhsParts.push('ingredients it grows or makes on the spot (time only)');const lhs=lhsParts.join(' + ')||(free?'nothing but time (made on the spot)':'nothing');const brought=containers.filter(c=>/full/i.test(c.r?.name||'')),reused=containers.filter(c=>!brought.includes(c));return `<li><strong>${g.products.map(x=>`${fmt(x.count)} <a class="resource-link" href="${url('resources',x.r.id)}">${esc(x.r.name)}</a>`).join(' + ')}</strong> ← ${brought.length?`${brought.map(c=>`${fraction(c.amount)} ${esc(c.r?.name.replace(/Full$/,' (full)')||'')}`).join(' + ')} brought back by the workers${inputs.length?' + ':''}`:''}${inputs.length?lhs:brought.length?'':lhs}${reused.length?` <span class="objective-note">(${reused.map(c=>`${fraction(c.amount)} ${esc(c.r?.name||'container')}`).join(', ')} reused)</span>`:''}${g.notes.length?` <span class="objective-note">(${g.notes.join('; ')})</span>`:''}</li>`}).join('')}</ul><p class="small">Read from the stored steps: fuel and intermediates are folded into the inputs, containers that come back from the eating or drinking spots are marked reused, and “any of” means the step takes whichever is available. Per-cycle speed is not stored.</p>`}
