function rawBiomeBody(o){const b=biomeRule(o);if(!b)return '<p>No biome configuration decoded.</p>';const list=(key)=>b[key]?.length?'<ul>'+b[key].map(x=>'<li>'+assignedLink(x)+'</li>').join('')+'</ul>':'<p class="small">Not established. An empty recovered list is not proof of absence.</p>';const sources=(b.resource_sources||[]).filter(x=>!/decoration|cosmetic/i.test(x.asset_path)&&!/fish/i.test(x.name));return `${o.id==='Winter'?observedBuilding({name:'Greenhouse'}):''}<div class="tags">${o.id==='Green'?tag('Default / baseline · user report'):tag('Compared with Evergreen','gray')}${tag(b.source?'Sandbox configuration':'No configuration decoded','gray')}</div><p class="small">These are sandbox biome assignments. Campaign and challenge maps may override available crops, sources and buildings.</p><div class="biome-lists"><section class="panel"><h2>Crops</h2>${list('crops')}${b.farming_context?`<p class="small">${esc(b.farming_context)}</p>`:''}</section><section class="panel"><h2>Orchard plants</h2>${list('orchard_plants')}</section><section class="panel"><h2>Forestry</h2>${list('forester_plants')}</section><section class="panel"><h2>Configured resource sources</h2>${sources.length?'<ul>'+sources.map(x=>'<li>'+assignedLink(x)+'</li>').join('')+'</ul>':'<p class="small">Resource sources are not established.</p>'}<p class="small">Actual yields and map-level availability are unverified. Decorative fish objects are excluded from resource claims.</p></section></div><section class="rule-section"><h2>Needs & hazards</h2>${b.special_needs_and_hazards?.length?b.special_needs_and_hazards.map(t=>`<div class="prose"><p>${rich(t.text)}</p></div>`).join(''):'<p class="small">No special need or hazard has been established from the recovered configuration.</p>'}</section><section class="rule-section"><h2>Biome buildings</h2>${list('placeables')}</section>${availabilitySection('biomes',o)}${source({source:b.source,scope:b.source_scope,limitations:b.limitations,assignments:b},'Biome assignment evidence')}`}
