function scenarioAsset(x){if(!x)return '—';if(x.name&&/Variant_/.test(x.name)&&!B[x.gameobject_id])return esc(x.name.replace(/\s*Variant_(\w+)/,' ($1)'));const b=B[x.gameobject_id],r=Rkey[x.localization_key];return b?`<a href="${url('buildings',b.gameobject_id)}">${esc(b.name)}</a>`:r?`<a href="${url('resources',r.id)}">${esc(x.name)}</a>`:esc(x.name||x.guid||'Unresolved asset')}
