// Keep settlement (Housing) distinct from satisfaction of the Housing concern.
// Localization examples: Level01B, Single05_C_PeakResort, and leaderboard Create/Have.
function scenarioObjective(o){
 const kinds={Have:'Have',Create:'Produce / make',Consume:'Consume / recycle',VillagerCount:'Population',Happiness:'Happiness',Extract:'Extract',Concern:'Need satisfaction',Housing:'Settled',HaveInBuilding:'Have in building',ReachDay:'Reach day',GearedPercentage:'Equipped villagers',UseSocialSpot:'Use social spot'},comparison={Equal:'=',NotEqual:'≠',Less:'<',LessOrEqual:'≤',Greater:'>',GreaterOrEqual:'≥'};
 const relevant=['Have','Create','Consume','Extract','HaveInBuilding','GearedPercentage','UseSocialSpot'].includes(o.condition_name);
 let target=relevant?scenarioAsset(o.target):o.condition_name==='Concern'?esc(o.concern_name):'—';
 if(o.condition_name==='HaveInBuilding')target+=' in '+scenarioAsset(o.building);
 const percent=['Concern','Housing','Happiness','GearedPercentage'].includes(o.condition_name);
 const resource=o.target?.localization_key?.startsWith('Resource.');
 const meanings={Have:resource?'Have this amount in stock; making it earlier is not enough.':'Have this many of the target present.',Create:'Produce this amount over the scenario; this is a production total, not a stock target.',HaveInBuilding:'Have this amount in the specified building.',Housing:o.NeededAmount===100?'Have everyone settled.':'Have this percentage of villagers settled.',Concern:o.concern_name==='Housing'?'Satisfy Housing. This is a need-satisfaction objective, separate from “Have everyone settled”.':'Reach this level of satisfaction for the named need.',Happiness:'Reach this happiness percentage.',VillagerCount:'Reach this population.',GearedPercentage:'Equip this percentage of villagers with the target item.',ReachDay:'Reach the specified day.',Extract:'Extract this amount from the source.',Consume:'Consume the resource or recycle/remove the target; the action depends on the target.',UseSocialSpot:'Use the named social spot the required number of times.'};
 return `<tr><td>${esc(kinds[o.condition_name]||o.condition_name)}</td><td>${target}</td><td>${esc(comparison[o.comparison_name]||o.comparison_name)} ${esc(o.NeededAmount)}${percent?'%':''}</td><td>${esc(meanings[o.condition_name]||'See the objective source for details.')}</td></tr>`;
}
function objectiveResource(o){const key=o.target?.localization_key;if(!key||!key.startsWith('Resource.'))return null;return D.resources.find(r=>r.localization_key===key&&r.publicly_named)||null}
function recipeForLevel(r,level){const entries=D.resources.filter(x=>x.name===r.name).flatMap(x=>x.made_from||[]);if(!entries.length)return null;const buildable=new Set((level.scenario?.buildable_entries||[]).map(x=>x.gameobject_id)),isTrade=m=>/trading/i.test(m.building_name);return entries.find(m=>buildable.has(m.building_id)&&!isTrade(m))||entries.find(m=>!isTrade(m))||null}
function harvesters(r){return uniq(D.buildings.filter(b=>!b.is_plant&&!b.name.startsWith('_')&&!isSuppressed('buildings',b.gameobject_id)&&b.formula_ids.some(i=>{const f=F[i];return f&&f.outputs.some(o=>R[o.resource_id]?.name===r.name)&&(f.resource_source_category_ids?.length||f.inputs.every(x=>R[x.resource_id]?.name===r.name))})))}
function mapDrop(r){return Object.values(DM.plants?.records||{}).some(p=>(p.spawners||[]).some(sp=>sp.spawns===r.name))}
function cropSources(r){return uniq(D.buildings.filter(b=>b.is_plant&&plantKind(b)==='crop'&&!isSuppressed('buildings',b.gameobject_id)&&b.formula_ids.some(i=>F[i]?.outputs.some(o=>R[o.resource_id]?.name===r.name))))}
function gatherSource(r,level){if(mapDrop(r))return {kind:'drop'};const here0=new Set((level.scenario?.buildable_entries||[]).map(x=>x.gameobject_id)),crops=cropSources(r);if(crops.length){const on=crops.filter(b=>[b,...(b.variants||[])].some(v=>here0.has(v.gameobject_id)));return {kind:'crop',plants:on.length?on:crops,onMap:on.length>0}}let hs=harvesters(r);const planters=new Set(Object.keys(PLANTER_SOURCE).flatMap(k=>planterBuildings(k).map(b=>b.name))),plain=hs.filter(b=>!planters.has(b.name));if(plain.length)hs=plain;const here=new Set((level.scenario?.buildable_entries||[]).map(x=>x.gameobject_id)),avail=b=>[b,...(b.variants||[])].some(v=>here.has(v.gameobject_id));if(hs.length){const on=hs.filter(avail);return {kind:'harvest',buildings:on.length?on:hs,onMap:on.length>0}}return null}
function expandNeeds(level,wanted){const totals=new Map(),add=(r,count,direct,via)=>{const t=totals.get(r.name)||{resource:r,direct:0,indirect:0,via:null};if(direct)t.direct+=count;else t.indirect+=count;if(via)t.via=via;totals.set(r.name,t)},steps=[];
 const walk=(r,count,direct,trail)=>{add(r,count,direct);const g=gatherSource(r,level);if(g){totals.get(r.name).gather=g;return}const m=recipeForLevel(r,level);if(!m||trail.includes(r.name))return;const parts=m.per_unit.map(x=>({resource:R[x.resource_id],count:x.count*count})).filter(x=>x.resource);steps.push({resource:r,count,building:m,parts});for(const part of parts){walk(part.resource,part.count,false,[...trail,r.name])}};
 for(const w of wanted)walk(w.resource,w.count,true,[]);
 for(const st of steps){const t=totals.get(st.resource.name);if(t)t.via=st.building}
 return {totals:[...totals.values()].filter(t=>t.direct+t.indirect>0),steps}}
function objectiveNeedsSection(level){const s=level.scenario;if(!s)return '';const byObjective=sec=>{const m=new Map();for(const o of s.objectives.filter(x=>x.IsSecondary===sec&&['Have','Create'].includes(x.condition_name))){const r=objectiveResource(o);if(!r)continue;m.set(r.id,{resource:r,count:(m.get(r.id)?.count||0)+o.NeededAmount})}return [...m.values()]};
 const main=byObjective(false),optional=byObjective(true);if(!main.length&&!optional.length)return '';
 const mainRoll=expandNeeds(level,main),allRoll=expandNeeds(level,[...main,...optional]),round=n=>Math.ceil(n-1e-9),rlink=r=>`<a class="resource-link" href="${url('resources',r.id)}">${esc(r.name)}</a>`,blink=m=>`<a href="${url('buildings',m.building_id)}">${esc(m.building_name)}</a>`;
 const gatherCell=(r,g,level)=>{if(g.kind==='drop'){const m=recipeForLevel(r,level);return `picked up near trees${m?`; the ${blink(m)} can also make them`:''}`}if(g.kind==='crop')return `grown in fields: ${joinNames(g.plants.map(b=>`<a href="${url('buildings',b.gameobject_id)}">${esc(b.name)}</a>`))}${g.onMap?'':' <span class="objective-note">(none plantable on this map)</span>'}`;return `from the ${joinNames(g.buildings.map(b=>`<a href="${url('buildings',b.gameobject_id)}">${esc(b.name)}</a>`))}${g.onMap?'':' <span class="objective-note">(not buildable on this map)</span>'}`};
 const rows=[...allRoll.totals].sort((a,b)=>(b.direct>0)-(a.direct>0)||(b.direct+b.indirect)-(a.direct+a.indirect)).map(t=>{const mt=mainRoll.totals.find(x=>x.resource.name===t.resource.name),here=new Set((s.buildable_entries||[]).map(x=>x.gameobject_id));return `<tr><td>${icon('resources',t.resource)}${rlink(t.resource)}</td><td>${mt?fmt(round(mt.direct+mt.indirect)):'—'}</td><td>${fmt(round(t.direct+t.indirect))}</td><td>${t.direct?fmt(round(t.direct)):'—'}</td><td>${t.gather?gatherCell(t.resource,t.gather,level):t.via?blink(t.via)+(here.has(t.via.building_id)?'':' <span class="objective-note">(not buildable on this map)</span>'):'<span class="unknown">gathered or traded</span>'}</td></tr>`}).join('');
 const chain=allRoll.steps.map(st=>`<li>${fmt(round(st.count))} ${rlink(st.resource)} at the ${blink(st.building)} needs ${st.parts.map(x=>`${fmt(round(x.count))} ${rlink(x.resource)}`).join(' + ')}</li>`).join('');
 return `<section class="rule-section" id="objective-needs"><h2>What the objectives need</h2><p>Items the objectives ask for, plus the ingredients to make them, worked back through each recipe${s.buildable_entries?.length?' using the buildings this map offers':''}. Amounts are rounded up to whole items; allow extra for anything villagers use along the way. Items that can be picked up or harvested from the map stop there rather than being worked back through a factory.</p><div class="table-wrap"><table><thead><tr><th>Resource</th><th>Main objectives</th><th>Main + optional</th><th>Of which asked for directly</th><th>Made at</th></tr></thead><tbody>${rows}</tbody></table></div><details><summary>How the totals were worked out</summary><ul class="recipe-steps">${chain}</ul></details><p class="small">Construction materials for the buildings themselves are not included yet. Recipe ratios come from each resource's stored recipe; see the resource pages for their evidence.</p></section>`}
function levelBody(o){const s=o.scenario;if(!s)return legacyLevelBody(o);const cfg=s.level_config[0]||{},needs=[['Food','Food'],['Housing','Housing'],['Community','Community'],['Entertainment','Fun'],['Heat','Heat'],['Wellness','Wellness'],['Refreshment','Cooling'],['Hydration','Hydration / thirst']];const build=[...new Map(s.buildable_entries.map(x=>[x.guid,x])).values()],plants=build.filter(x=>B[x.gameobject_id]?.is_plant||x.localization_key?.startsWith('Plant.')),other=build.filter(x=>!plants.includes(x));const objectiveTable=secondary=>{const os=s.objectives.filter(x=>x.IsSecondary===secondary);return os.length?`<div class="table-wrap"><table><thead><tr><th>Condition</th><th>Target</th><th>Required value</th><th>What counts</th></tr></thead><tbody>${os.map(scenarioObjective).join('')}</tbody></table></div>`:'<p>None.</p>'};const assetList=items=>items.length?'<ul>'+items.map(x=>'<li>'+scenarioAsset(x)+'</li>').join('')+'</ul>':'<p>No entries in this group.</p>';return `<div class="prose"><p>${rich(o.description)}</p></div><div class="tags">${tag('Decoded scenario')}${tag('Objectives cross-checked')}</div><p class="small">Stored map configuration for version 30, build 254. Packaged content does not establish live menu availability.</p><div class="fact-grid facts-4"><div class="fact"><small>Biome</small><b>${biomeCell(o)}</b></div><div class="fact"><small>Main objectives</small><b>${s.primary_objective_count}</b></div><div class="fact"><small>Optional objectives</small><b>${s.optional_objective_count}</b></div><div class="fact"><small>Day limit</small><b>${s.day_limit===-1?'No day limit':s.day_limit===null?'Not set':s.day_limit+' days'}</b></div></div>${startingConditions(s)}<section class="rule-section"><h2>Main objectives</h2>${objectiveTable(false)}<h2>Optional objectives</h2>${objectiveTable(true)}<p class="small">Values and comparisons match both the header and world records. Percentage units distinguish satisfaction, settled villagers and equipment from item counts. Settlement wording is supported by Level01B; Cliffside Resort separately says “Satisfy Housing”. “Consume / recycle” is an internal condition whose wording depends on the target.</p></section>${objectiveNeedsSection(o)}${strategySection(o)}<section class="rule-section"><h2>Villager needs</h2><div class="table-wrap"><table><thead><tr><th>Need</th><th>Active on this map</th></tr></thead><tbody>${needs.map(([key,label])=>{const k='IsConcern'+key+'Available';return `<tr><td>${label}</td><td>${Object.hasOwn(cfg,k)?cfg[k]?'Yes':'No':'Not set (older map)'}</td></tr>`}).join('')}</tbody></table></div><p class="small">An absent field in an older map is not treated as disabled. Runtime defaults and migration remain unverified.</p></section><section class="rule-section"><h2>Available buildings & plants</h2><p>${build.length} buildings and plants can be built on this map from the start. Anything unlocked during play is not included.</p><div class="biome-lists"><section class="panel"><h3>Buildings, structures & decorations</h3>${assetList(other)}</section><section class="panel"><h3>Fields & plants</h3>${assetList(plants)}</section></div></section><section class="rule-section"><h2>Starting objects & resources</h2><p class="small">Counts below are serialized prefab entities. They do not establish harvest yields, stockpile units, or numbers of independent buildings; child entities and internal objects can be included.</p><details><summary>Show ${s.initial_prefab_instances.length} starting object types</summary><div class="table-wrap"><table><thead><tr><th>Object</th><th>Count</th></tr></thead><tbody>${s.initial_prefab_instances.map(x=>`<tr><td>${scenarioAsset(x)}</td><td>${x.instance_count}</td></tr>`).join('')}</tbody></table></div></details></section>${source({text_asset_id:s.text_asset_id,source_level_path:s.source_level_path,sha256:s.sha256,world_objectives_match_header:s.world_objectives_match_header,level_config:s.level_config},'Scenario decoding evidence')}<section class="rule-section"><h2>Remaining checks</h2>${checks(['Confirm current menu category and release availability.','Check runtime unlocks and defaults for need fields absent in legacy maps.','Measure yields, need decay, production rates and other runtime effects.'])}</section>`}

function scenarioNeedSummary(s){const labels={Food:"Food",Housing:"Housing",Community:"Community",Entertainment:"Fun",Heat:"Heat",Wellness:"Wellness",Refreshment:"Cooling",Hydration:"Hydration"};return Object.entries(s.level_config[0]||{}).filter(([k,v])=>k.startsWith("IsConcern")&&v===true).map(([k])=>labels[k.slice(9,-9)]||k).join(", ")||"None"}

function biomeBody(o){const b=biomeRule(o);return `${o.id==='Winter'?observedBuilding({name:'Greenhouse'}):''}<section class="rule-section"><h2>Needs & environment</h2>${(b?.special_needs_and_hazards||[]).map(t=>`<p>${rich(t.text)}</p>`).join('')||'<p>See individual scenarios for their enabled needs.</p>'}</section>${weatherSection(o)}<section class="rule-section"><h2>Plants & buildings</h2><p>Available plants and buildings depend on the scenario. Each scenario page lists its own planting and building options.</p><a href="${url('levels')}">Browse scenarios</a></section>${biomeSpawnSection(o)}${biomeLevelsSection(o)}${source(b,'Sandbox biome data — interpretation under review')}`;}
// Reader pages and research pages share one source renderer; research material is moved, not discarded.
function rawArticle(type,id){if(type==='buildings')return buildingPage(B[id]);if(type==='resources')return resourcePage(R[id]);if(type==='chains')return chainPage(B[id]);const list=type==='heroes'?W.leaders:W[type];return worldPage(type,list.find(x=>String(x.id)===String(id)))}
function pullBlocks(html,tagName,predicate){const re=new RegExp('<\\/?'+tagName+'\\b[^>]*>','gi'),stack=[],spans=[];let m;while((m=re.exec(html))){if(m[0].startsWith('</')){const begin=stack.pop();if(begin!==undefined){const text=html.slice(begin,re.lastIndex);if(predicate(text))spans.push([begin,re.lastIndex,text])}}else stack.push(m.index)}const top=spans.filter(s=>!spans.some(p=>p!==s&&p[0]<s[0]&&p[1]>=s[1])).sort((a,b)=>a[0]-b[0]);let clean='',pos=0;for(const [start,end]of top){clean+=html.slice(pos,start);pos=end}clean+=html.slice(pos);return {html:clean,blocks:top.map(x=>x[2])}}
function splitResearch(html){let notes=[];for(const [tag,pred] of [['details',s=>/^<details\b[^>]*class="source"/.test(s)],['aside',s=>/^<aside\b[^>]*class="detail-aside"/.test(s)],['section',s=>/^<section\b[^>]*>\s*<h2>(Pending verification|Gameplay checks|Remaining checks|What still needs checking|Biome assignments|Sandbox biome references|Content availability)<\/h2>/.test(s)],['div',s=>/^<div\b[^>]*class="notice\b/.test(s)]]){const out=pullBlocks(html,tag,pred);html=out.html;notes.push(...out.blocks)}
 const paragraphs=pullBlocks(html,'p',s=>/^<p\b[^>]*class="small"/.test(s)&&/verif|not tested|untested|decoded|stored map configuration|runtime|source tables|internal condition|not establish/i.test(s));html=paragraphs.html;notes.push(...paragraphs.blocks);
 html=html.replace(/<span class="tag[^"\n]*">(?:Needs gameplay verification|Decoded[^<]*|Recovered[^<]*|Objectives cross-checked|Unknown|Release unconfirmed|Sandbox configuration|No configuration decoded|Derived from[^<]*|Game text)<\/span>/g,'').replace(/<div class="tags">\s*<\/div>/g,'').replace(/<div><dt>(?:Work range \(raw units\)|Work schedule \(raw cycle\)|Gameplay verification|Game verification|Objective quantities|Internal name|Data version|Packaged map)<\/dt><dd>[\s\S]*?<\/dd><\/div>/g,'');
 return {html,notes};}
function readerArticle(html,type,id){const {html:clean}=splitResearch(html);const rec=pageLookup[type+'/'+id];return clean+`<p class="article-evidence-link"><a href="${url('evidence',type+'/'+id)}">Sources & research notes for this page</a></p>`+contributionLinks(type,id,rec?.name||'')}
function researchPage(id){const slash=id.indexOf('/'),type=id.slice(0,slash),key=id.slice(slash+1),rec=pageLookup[type+'/'+key];if(!rec)return empty();const original=rawArticle(type,key),split=splitResearch(original);let extra='';if(type==='buildings'){const b=B[key];extra=pilesResearch(b)+source({work_schedule:b.workplace_config?.WorkTimeRange,interpretation:'Normalized work-cycle interval; time origin and clock mapping unverified.'},'Work schedule fields');if(b.is_plant){const g=growthFor(b);if(g)extra+=`<section class="rule-section"><h2>Growth stages</h2><p>The sapling definition stores ${g.stages.length} stages totalling ${fmt(g.total_configured_stage_days)} days: ${esc(g.stages.map(x=>fmt(x.days_duration)).join(' + '))}. ${esc(g.caveat||'')} Nobody has timed this plant in play, so whether a stored day equals a clock day, and whether the last stage is the harvestable state or a wait before it, are open questions.</p>${source(g,'Sapling growth definition')}</section>`;extra+=biomeResearch(b)}extra+=productionModelResearch(b);if(b.gameplay){const g=b.gameplay;extra+=`<section class="rule-section"><h2>Gameplay facts and their evidence</h2>${g.recipe_per_cycle?`<p><strong>Recipe per cycle</strong> (${esc(g.recipe_per_cycle.status)}): ${esc(g.recipe_per_cycle.inputs.map(x=>`${fmt(x.count)} ${x.name}`).join(' + '))} → ${esc(g.recipe_per_cycle.outputs.map(x=>`${fmt(x.count)} ${x.name}`).join(' + '))}. ${esc(g.recipe_per_cycle.evidence.kind)}, ${esc(g.recipe_per_cycle.evidence.date)}: ${esc(g.recipe_per_cycle.evidence.reference)}</p>`:''}${g.output_capacity?`<p><strong>Output capacity</strong> (${esc(g.output_capacity.status)}): ${g.output_capacity.count} ${esc(g.output_capacity.name)}. ${esc(g.output_capacity.evidence.kind)}, ${esc(g.output_capacity.evidence.date)}: ${esc(g.output_capacity.evidence.reference)}</p>`:''}${source(g,'Gameplay block')}</section>`}
 if(b.name==='Clay Pit')extra+=`<h2>Do clay workers sleep in?</h2><p>The Clay Pit stores a work interval of 0 → 0.6 while 53 workplaces, including Farm and Bakery, store 0.9 → 0.5. The shift starts and finishes a tenth of a day later than the standard one and has the same length, which matches the community report of late risers. Quarry, Orchard and Foresters' Hub store 0 → 0.5: the same late start with a standard finish. Which clock hour fraction 0 corresponds to, and whether the crew also sleeps longer, have not been verified.</p>`;}
 return `${header(rec.name+' — sources & research','Evidence, decoding details and open questions for this article.','RESEARCH')}<p><a href="${url(type,key)}">← ${esc(rec.name)}</a></p>${split.notes.join('')}${extra}${contributionNotes(type,key)}${observationLink(type,key,rec.name)}`;}
function biomeResearch(b){const related=N.biomes.filter(n=>['crops','orchard_plants','forester_plants','placeables'].some(k=>n[k]?.some(x=>x.wiki_refs?.some(ref=>ref.id===b.source.path_id||ref.id===b.gameobject_id))));return `<section class="rule-section"><h2>Sandbox biome references</h2><p>These are references in sandbox configuration, not a verified crop-availability table. Shared defaults, exclusions, farm compatibility and runtime filtering still need interpretation.</p><ul>${related.map(n=>`<li>${esc(n.name)}</li>`).join('')}</ul>${source(related.map(n=>({biome:n.name,source:n.source,assignments:n.crops,exclusions:n.excluded_base_placeables})),'Sandbox assignment records')}</section>`}
function cropPage(b){const maps=W.levels.filter(l=>l.scenario?.buildable_entries.some(x=>x.gameobject_id===b.gameobject_id));const farm=D.buildings.find(x=>x.name==='Farm');return `${crumbs('plants',b.name)}<div class="detail-head"><div class="detail-icon">${icon('buildings',b)}</div><div><p class="eyebrow">PLANT</p><h1>${esc(b.name)}</h1></div></div><article>${buildingInfobox(b)}${verifyBadge('buildings',b.gameobject_id)}<p>${({orchard:'A fruit tree',forestry:'A forestry tree',crop:'A field crop'})[plantKind(b)]}${mainYield(b)?` that yields ${mainYield(b)}`:plantYield(b)?` that yields ${plantYield(b)}`:''}. ${plantKind(b)==='crop'?`Planted and harvested by the ${plantedBy(b)}`:`Planted by the ${plantedBy(b)}${harvestedBy(b)?` and harvested by the ${harvestedBy(b)}`:''}`}.${growthText(b)?` It grows in ${growthText(b)}.`:''}${plantBiomes(b).length?` In sandbox it can be planted in ${joinNames(plantBiomes(b).map(biomeLink),'and')}.`:''}</p>${b.description?`<div class="prose"><p>${rich(b.description)}</p></div>`:''}${plantBiomeSection(b)}${maps.length?scenarioBacklinks(b):'<section class="rule-section"><h2>Where it can be planted</h2><p>No matching scenario planting list was found.</p></section>'}${source(b,'Plant definition')}${biomeResearch(b)}${historySection('buildings',b.gameobject_id)}${navbox('buildings',b)}</article>`}
function friendlyTerm(key){const base=key.split('.').slice(0,2).join('.'),plural=/Plural/.test(key);return W.terms?.[key]||W.terms?.[base+(plural?'.NamePlural':'.Name')]||null}
function rich(s){return esc(s||'').replace(/&lt;\/?(?:style(?:=[^&]*?)?|size(?:=[^&]*?)?)&gt;/g,'').replace(/&lt;(\/?)b&gt;/g,'<$1strong>').replace(/\n/g,'<br>').replace(/\{([^}]+)\}|\[((?:Resource|Building|Sources|Field|Tree)\.[^\]]+)\]/g,(_,a,b)=>{const key=a||b,base=key.split('.').slice(0,2).join('.'),label=friendlyTerm(key);if(Bkey[base])return `<a class="resource-link" href="${url('buildings',Bkey[base].gameobject_id)}">${esc(Bkey[base].name)}</a>`;if(Rkey[base])return `<a class="resource-link" href="${url('resources',Rkey[base].id)}">${esc(label||Rkey[base].name)}</a>`;if(label)return esc(label);if(/count|amount|days|value|percentage/i.test(key))return 'target quantity';return esc(key.replace(/\.(WithIconPlural|WithIcon|NamePlural|Name)$/,'').split('.').at(-1).replace(/([a-z])([A-Z])/g,'$1 $2'))})}

function contributionNotes(type,id){const rows=(W.contributions||[]).filter(x=>x.target.type===type&&String(x.target.id)===String(id));return rows.length?`<section class="rule-section"><h2>Contributed observations</h2>${rows.map(x=>`<article><h3>${esc(x.claim)}</h3><p>Status: ${esc(x.status)} · ${esc(x.evidence.kind)} · ${esc(x.evidence.game_version)}</p><p>${esc(x.evidence.reference)}</p><p>${esc(x.notes||'')}</p></article>`).join('')}</section>`:''}
function mdInline(s){return esc(s).replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\[([^\]]+)\]\((https:\/\/[^)]+)\)/g,'<a href="$2">$1</a>').replace(/\(#(\d+)\)/g,`(<a href="${GITHUB}/pull/$1">#$1</a>)`)}
function mdBlocks(text,{skipTitle=true,h2='h2'}={}){let html='',list='';for(const line of text.split('\n')){const ordered=/^\d+\. /.test(line),bullet=/^- /.test(line);if(!ordered&&!bullet&&list){html+=`</${list}>`;list=''}if(/^# /.test(line)){if(!skipTitle)html+=`<h1>${mdInline(line.slice(2))}</h1>`}else if(/^## /.test(line)){html+=`<${h2}>${mdInline(line.slice(3))}</${h2}>`}else if(ordered||bullet){const wanted=ordered?'ol':'ul';if(list!==wanted){if(list)html+=`</${list}>`;html+=`<${wanted}>`;list=wanted}html+=`<li>${mdInline(line.replace(/^(?:- |\d+\. )/,''))}</li>`}else if(line.trim())html+=`<p>${mdInline(line)}</p>`}if(list)html+=`</${list}>`;return html}
function contributionPage(){function inline(s){return esc(s).replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\[([^\]]+)\]\((https:\/\/[^)]+)\)/g,'<a href="$2">$1</a>')}let html='',list='';for(const line of W.contribution_guide.split('\n')){const ordered=/^\d+\. /.test(line),bullet=/^- /.test(line);if(!ordered&&!bullet&&list){html+=`</${list}>`;list=''}if(/^# /.test(line)){html+=header(line.slice(2),'Help improve a sourced, community-maintained reference.','CONTRIBUTE')}else if(/^## /.test(line)){html+=`<h2>${inline(line.slice(3))}</h2>`}else if(ordered||bullet){const wanted=ordered?'ol':'ul';if(list!==wanted){if(list)html+=`</${list}>`;html+=`<${wanted}>`;list=wanted}html+=`<li>${inline(line.replace(/^(?:- |\d+\. )/,''))}</li>`}else if(line.trim())html+=`<p>${inline(line)}</p>`}if(list)html+=`</${list}>`;return '<div class="prose contribution-guide">'+html+'</div>'}

let fullWorld,publicWorld,fullBiomes,publicBiomes,fullRules,publicRules;
function spoilerEntry(type,id){if(type==='chains')type='buildings';const entries=(fullWorld||W)?.spoiler_policy?.entries||[];return entries.find(x=>x.type===type&&String(x.id)===String(id));}
function initializeSpoilers(){fullRules=D;fullWorld=W;fullBiomes=N;publicRules={...D,buildings:D.buildings.filter(b=>!spoilerEntry('buildings',b.gameobject_id)&&!isSuppressed('buildings',b.gameobject_id)),resources:D.resources.filter(r=>!spoilerEntry('resources',r.id))};publicWorld={...W,levels:W.levels.filter(x=>!spoilerEntry('levels',x.id)),leaders:W.leaders.filter(x=>!spoilerEntry('heroes',x.id)),biomes:W.biomes.filter(x=>!spoilerEntry('biomes',x.id)),campaigns:W.campaigns.map(x=>({...x,level_ids:x.level_ids.filter(id=>!spoilerEntry('levels',id))})),stories:W.stories.filter(x=>!W.spoiler_policy.entries.some(e=>e.type==='heroes'&&(x.id===W.leaders.find(l=>l.id===e.id)?.name||x.name.includes(W.leaders.find(l=>l.id===e.id)?.name)))),ui_observations:{...W.ui_observations,availability:'Additional packaged content is listed separately in the Spoilers section.'}};publicBiomes={...N,biomes:N.biomes.filter(x=>!spoilerEntry('biomes',x.id))};}
function applySpoilerScope(type,id){const research=type==='evidence'?spoilerEntry(id.split('/')[0],id.slice(id.indexOf('/')+1)):null;const allow=type==='spoilers'||spoilerEntry(type,id)||research;W=allow?fullWorld:publicWorld;N=allow?fullBiomes:publicBiomes;D=allow?fullRules:publicRules;}
function spoilerWarning(type,id){const e=spoilerEntry(type,id);return `<aside class="notice"><div><strong>Spoilers: unreleased or release-unconfirmed content</strong><p>${esc(e.reason)} Status recorded ${esc(e.as_of)}.</p><a href="${url('spoilers')}">Spoiler index</a> · <a href="${url('')}">Return to the regular guide</a></div></aside>`;}
function spoilersHomeSection(){return `<section class="rule-section spoiler-home"><h2>Spoilers</h2><p>Looking to look ahead? Check out the spoilers section.</p><a href="${url('spoilers')}">Browse Spoilers →</a></section>`;}
function spoilersPage(){return `${header('Spoilers','This section contains reported-unreleased content and closely associated material whose release is unconfirmed. Names and details below may spoil future updates.','OPTIONAL CONTENT')}<p>Placement here is editorial; it does not establish a release date. Other entries with unknown release status are not automatically treated as unreleased.</p><section class="rule-section"><h2>How we tell that something is unreleased</h2><p>Every prefab in the game files carries a version gate (the <code>MinGameVersion</code> field on its key component). The game hides an object whose gate is higher than the running game version. The installed build reports version ${DM?.min_game_version?.current_game_version??30}, and most prefabs store 0 or a version at or below it. An entry is marked <strong>confirmed unreleased</strong> only when its own prefab root stores a gate above the installed version; in this build that gate is 32. Entries are marked <strong>reported unreleased</strong> when the evidence is a maintainer or player report, and <strong>related, release unconfirmed</strong> when they merely belong with gated content (a scenario or biome that only exists for it) and have no gate of their own. Gates also give the update that added released content: building and resource infoboxes show it as “Added in update N”.</p></section><p><a href="${url('')}">Return to the regular guide</a></p>${['resources','buildings','chains','heroes','levels','biomes','tournament'].map(type=>{const entries=fullWorld.spoiler_policy.entries.filter(x=>x.type===type);if(!entries.length)return '';return `<section class="rule-section"><h2>${({resources:'Resources & food',buildings:'Buildings',chains:'Production chains',heroes:'Leaders',levels:'Scenarios',biomes:'Biomes',tournament:'Tournament seasons'})[type]}</h2><ul>${entries.map(e=>{const obj=type==='tournament'?{name:tournamentText(`FastMode.${e.id}.Name`)||e.id}:(['buildings','chains'].includes(type)?fullRules.buildings:type==='resources'?fullRules.resources:type==='heroes'?fullWorld.leaders:fullWorld[type]).find(x=>String(x.gameobject_id||x.id)===String(e.id));return `<li><a href="${type==='tournament'?url('tournament','seasons'):url(type,e.id)}">${esc(obj.name)}</a> — ${esc(e.status==='reported-unreleased'?'Reported unreleased':'Related content; release unconfirmed')}<p>${esc(e.reason)}</p></li>`}).join('')}</ul></section>`}).join('')}`;}

// Companion-layer helpers: infoboxes, backlinks, grouped availability, story context, navboxes and contribution links.
const GITHUB='https://github.com/kellan/outlanders2-wiki';
const CATEGORY_LABELS={production:'Production building',homes:'Housing',fields:'Field or plant',other:'Structure or decoration'};
function contentFile(type,id){const folder={buildings:'buildings',chains:'buildings',resources:'resources',levels:'scenarios',heroes:'leaders',biomes:'biomes'}[type];return folder?`content/${folder}/${id}.json`:null}
function storyOf(levelId){return W.stories.find(s=>s.level_ids?.includes(levelId))}
function campaignOf(levelId){return W.campaigns.find(c=>c.level_ids.includes(levelId))}
function levelLink(l,extra=''){return `<a href="${url('levels',l.id)}">${esc(l.name)}</a>${extra}`}
function levelGroups(levels,extra=()=>''){
 const byId=new Map(levels.map(l=>[l.id,l]));const groups=[];const seen=new Set();
 for(const c of W.campaigns){const stories=W.stories.filter(s=>s.campaign_id===c.id).sort((a,b)=>a.menu_order-b.menu_order);const rows=[];
  for(const s of stories){const hits=(s.level_ids||[]).filter(i=>byId.has(i));if(!hits.length)continue;hits.forEach(i=>seen.add(i));rows.push(`<li><strong>${esc(s.name)}</strong>: ${hits.map(i=>levelLink(byId.get(i),extra(byId.get(i)))).join(', ')}</li>`)}
  const loose=c.level_ids.filter(i=>byId.has(i)&&!seen.has(i));if(loose.length){loose.forEach(i=>seen.add(i));rows.push(`<li><strong>Other levels</strong>: ${loose.map(i=>levelLink(byId.get(i),extra(byId.get(i)))).join(', ')}</li>`)}
  if(rows.length)groups.push({title:`<a href="${url('campaigns',c.id)}">${esc(c.name)}</a>`,html:`<ul class="level-groups">${rows.join('')}</ul>`,count:rows.length})}
 const rest=levels.filter(l=>!seen.has(l.id)),named=rest.filter(l=>!/^Unnamed scenario/.test(l.name)&&l.category!=='tournament_tutorial'),tutorials=rest.filter(l=>l.category==='tournament_tutorial'),unnamed=rest.filter(l=>/^Unnamed scenario/.test(l.name)&&l.category!=='tournament_tutorial');
 const links=ls=>`<div class="reference-links">${ls.sort((a,b)=>a.name.localeCompare(b.name)).map(l=>levelLink(l,extra(l))).join('')}</div>`;
 if(named.length)groups.push({title:'Standalone &amp; challenge maps',html:links(named)});
 if(tutorials.length)groups.push({title:'Tutorials',html:links(tutorials)});
 if(unnamed.length)groups.push({title:'',html:`<details><summary>${unnamed.length} unnamed archive map${unnamed.length>1?'s':''}</summary>${links(unnamed)}</details>`});
 return groups;
}
function groupedLevels(levels,extra){return levelGroups(levels,extra).map(g=>`${g.title?`<h3>${g.title}</h3>`:''}${g.html}`).join('')}
function objectiveTargets(predicate){const rows=[];for(const l of W.levels){const os=(l.scenario?.objectives||[]).filter(o=>['Have','Create','Consume','Extract','HaveInBuilding','GearedPercentage','UseSocialSpot'].includes(o.condition_name)&&predicate(o));if(os.length)rows.push({level:l,objectives:os})}return rows}
function objectiveText(o){const kinds={Have:'Have',Create:'Create',Consume:'Consume',Extract:'Extract',HaveInBuilding:'Have in building',GearedPercentage:'Equipped villagers',UseSocialSpot:'Use'},comparison={Equal:'=',NotEqual:'≠',Less:'<',LessOrEqual:'≤',Greater:'>',GreaterOrEqual:'≥'};return `${kinds[o.condition_name]||o.condition_name} ${comparison[o.comparison_name]||''} ${fmt(o.NeededAmount)}${o.IsSecondary?' (optional)':''}`}
function objectiveBacklinks(label,rows){if(!rows.length)return '';const byId=new Map(rows.map(r=>[r.level.id,r]));return `<section class="rule-section"><h2>Level objectives that need ${esc(label)}</h2><p class="small">Required amounts as set in each of ${rows.length} level${rows.length>1?'s':''}.</p>${groupedLevels(rows.map(r=>r.level),l=>` <span class="objective-note">${byId.get(l.id).objectives.map(objectiveText).map(esc).join('; ')}</span>`)}</section>`}
function plantKind(b){return b.paths.some(p=>p.includes('/orchard/'))?'orchard':b.paths.some(p=>p.includes('/forester/'))?'forestry':'crop'}
const PLANTER_SOURCE={crop:'Sources.Field',orchard:'Sources.FruitTree',forestry:'Sources.Tree'};
function planterBuildings(kind){const key='{'+PLANTER_SOURCE[kind]+'.';return uniq(D.buildings.filter(o=>!o.is_plant&&!isSuppressed('buildings',o.gameobject_id)&&/plant/i.test(o.description||'')&&(o.description||'').includes(key)))}
function biomeRefers(list,b){return (list||[]).some(x=>x.wiki_refs?.some(r=>r.kind==='building'&&(r.id===b.source?.path_id||r.id===b.gameobject_id)))}
function plantBiomes(b){return N.biomes.filter(n=>['crops','orchard_plants','forester_plants'].some(k=>biomeRefers(n[k],b)))}
function biomePlanters(n,kind){return planterBuildings(kind).filter(p=>[p,...(p.variants||[])].some(v=>biomeRefers(n.placeables,v)))}
function levelPlanters(b,kind){const all=planterBuildings(kind);const ids=new Set(W.levels.filter(l=>l.scenario?.buildable_entries.some(x=>x.gameobject_id===b.gameobject_id)).flatMap(l=>l.scenario.buildable_entries.map(x=>x.gameobject_id)));return all.filter(p=>[p,...(p.variants||[])].some(v=>ids.has(v.gameobject_id)))}
function plantersFor(b){const kind=plantKind(b),bs=plantBiomes(b);const list=bs.length?uniq(bs.flatMap(n=>biomePlanters(n,kind))):[];if(list.length)return list;const lv=levelPlanters(b,kind);return lv.length?lv:planterBuildings(kind)}
function buildingLink(o){return `<a href="${url('buildings',o.gameobject_id)}">${esc(o.name)}</a>`}
function plantedBy(b){const ps=plantersFor(b);return ps.length?joinNames(ps.map(buildingLink)):'—'}
function biomeLink(n){const w=W.biomes.find(x=>x.id===n.id);return w?`<a href="${url('biomes',w.id)}">${esc(n.name)}</a>`:esc(n.name)}
function wildBiomes(b){const root=DM.field_plants?.records?.[b.internal_name]?.plant;if(!root)return [];return N.biomes.map(n=>({biome:n,spawn:(n.resource_sources||[]).find(x=>x.asset_path?.replace(/^.*\//,'').replace(/\.prefab$/,'')===root&&x.density>0)})).filter(x=>x.spawn)}
function biomesRow(b){const bs=plantBiomes(b);return bs.length?bs.map(biomeLink).join(', '):null}
function wildRow(b){const ws=wildBiomes(b);return ws.length?ws.map(({biome,spawn})=>`${biomeLink(biome)} (${fmt(+spawn.density.toFixed(3))} per tile)`).join(', '):null}
function plantBiomeSection(b){const bs=plantBiomes(b),ws=wildBiomes(b);if(!bs.length&&!ws.length)return '';const kind=plantKind(b);const all=uniq([...bs,...ws.map(w=>w.biome)],n=>n.id);return `<section class="rule-section" id="biomes"><h2>Biomes</h2><p>Sandbox biomes that let you plant it, and the building that does the planting there. Story and challenge maps use their own planting lists, shown under “Where it can be planted”.</p><div class="table-wrap"><table><thead><tr><th scope="col">Biome</th><th scope="col">Planted by</th><th scope="col">Grows wild</th></tr></thead><tbody>${all.map(n=>{const ps=bs.some(x=>x.id===n.id)?biomePlanters(n,kind):[];const w=ws.find(x=>x.biome.id===n.id);return `<tr><td>${biomeLink(n)}</td><td>${ps.length?joinNames(ps.map(buildingLink),'or'):bs.some(x=>x.id===n.id)?'No planter for this plant type is in the biome’s sandbox build list':'Not plantable'}</td><td>${w?`Yes, ${fmt(+w.spawn.density.toFixed(3))} per tile`:'No'}</td></tr>`}).join('')}</tbody></table></div><p class="small">Decoded from each biome’s sandbox MapBiomeSettings (placeables and map spawns). Which building plants a crop is read from the building descriptions, which name the plant type each one handles. Not yet checked in play.</p></section>`}
function plantYield(b){const outs=[...new Set(b.formula_ids.flatMap(i=>F[i]?.outputs.map(o=>o.resource_id)||[]))].map(id=>R[id]).filter(Boolean);return outs.length?outs.map(r=>`<a href="${url('resources',r.id)}">${esc(r.name)}</a>`).join(', '):null}
function joinNames(items,word='or'){return items.length>1?items.slice(0,-1).join(', ')+' '+word+' '+items[items.length-1]:items[0]||''}
function harvestedBy(b){if(plantKind(b)==='crop')return plantedBy(b);const cats=new Set(b.formula_ids.flatMap(i=>F[i]?.resource_source_category_ids||[]));if(!cats.size)return null;const hs=uniq(D.buildings.filter(o=>!o.is_plant&&!isSuppressed('buildings',o.gameobject_id)&&o.formula_ids.some(i=>F[i]?.resource_source_category_ids.some(c=>cats.has(c)))));return hs.length?joinNames(hs.map(o=>`<a href="${url('buildings',o.gameobject_id)}">${esc(o.name)}</a>`)):null}
function growthText(b){const g=growthFor(b);if(!g)return null;const d=g.total_configured_stage_days,n=g.stages.length;return `${fmt(d)} day${d===1?'':'s'} (${n} stage${n===1?'':'s'})`}
function growthFor(b){const norm=s=>String(s).replace(/^Field\s*/,'').replace(/\s*Sapling\s*/,'').replace(/\s+/g,'').toLowerCase().replace(/tree$/,'');return D.growth?.find(g=>norm(g.name)===norm(b.internal_name))}
function infobox(type,o,rows,image){const body=rows.filter(r=>r&&r[1]!==null&&r[1]!==undefined&&r[1]!=='').map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${v}</dd></div>`).join('');return `<aside class="infobox"><div class="infobox-image">${image}</div><h3 class="infobox-title">${esc(o.name)}</h3><dl>${body}</dl></aside>`}
function plural(n,word){return `${fmt(n)} ${word}${n===1?'':'s'}`}
function mechRoot(name){return name||''}
function pilesFor(b){return (DM?.piles?.records||[]).filter(p=>p.root===b.internal_name)}
function pileResource(p){if(p.reference_resource){return D.resources.find(r=>r.internal_name===p.reference_resource&&r.publicly_named)||D.resources.find(r=>r.internal_name===p.reference_resource)||null}const ws=new Set(p.output_of_workspot_ids||[]);if(!ws.size)return null;const f=D.formulas.find(f=>(f.referencing_workspot_ids||[]).some(w=>ws.has(w)));const out=f?.outputs?.[0];return out?R[out.resource_id]||null:null}
function outputCapacity(b){const groups=new Map();for(const p of pilesFor(b).filter(p=>p.public_output)){const r=pileResource(p),key=r?r.name:'items',g=groups.get(key)||{resource:r,count:0,piles:0};g.count+=p.capacity;g.piles++;groups.set(key,g)}return [...groups.values()].sort((a,b)=>b.count-a.count)}
function capacityRow(b){const cap=b.gameplay?.output_capacity;if(cap)return `${cap.count} <a class="resource-link" href="${url('resources',cap.resource_id)}">${esc(cap.name)}</a> <span class="objective-note">(${cap.status==='disputed'?'disputed: ':''}${esc(cap.evidence.kind.replace('-',' '))})</span>`;const caps=outputCapacity(b);if(!caps.length)return null;return caps.map(g=>`${fmt(g.count)} ${g.resource?`<a class="resource-link" href="${url('resources',g.resource.id)}">${esc(g.resource.name)}</a>`:'finished items'} <span class="objective-note">(${plural(g.piles,'pile')} of ${fmt(g.count/g.piles)})</span>`).join('<br>')}
function heatSources(b){return (DM?.heat_sources?.records||[]).filter(h=>h.root===b.internal_name)}
function heatRow(b){const hs=heatSources(b);if(!hs.length)return null;return hs.map(h=>{const parts=[`burns one fuel item every ${h.consume_heat_in_days===1?'day':plural(h.consume_heat_in_days,'day')}`];if(h.heated_sleep_spots)parts.push(`warms ${plural(h.heated_sleep_spots,'sleeping spot')} (${fmt(h.social_spot_heat_units)} heat units)`);if(h.heated_social_spots)parts.push(`warms ${plural(h.heated_social_spots,'visitor spot')} (${fmt(h.social_spot_heat_units)} heat units)`);return parts.join('; ')}).join('<br>')}
function housingRow(b){if(b.sleep_spots===null)return null;const hs=(DM?.houses?.records||[]).filter(h=>h.root===b.internal_name),baby=hs.filter(h=>h.accept_only_babies).reduce((n,h)=>n+h.sleep_spots,0),pet=hs.filter(h=>/pet house/i.test(h.path)).reduce((n,h)=>n+h.sleep_spots,0);return `${plural(b.sleep_spots,'villager')}${baby||pet?` <span class="objective-note">plus ${[baby?(baby===1?'a crib':plural(baby,'crib')):'',pet?(pet===1?'a doghouse':plural(pet,'doghouse')):''].filter(Boolean).join(' and ')}</span>`:''}`}
function addedIn(rootName){const v=DM?.min_game_version?.roots?.[rootName];if(!v||!v.root_version)return null;const rel=(V.public_release_history||[]).find(x=>x.version===v.root_version),current=DM.min_game_version.current_game_version;return `Update ${v.root_version}${rel?` (${esc(rel.release_date)})`:v.root_version>current?' <span class="objective-note">(newer than the current game, not yet released)</span>':''}`}
function needLabel(n){return {Entertainment:'Fun',Refreshment:'Cooling',Energy:'Energy (sleep)'}[n]||n}
function houseList(){return uniq(D.buildings.filter(b=>!b.is_plant&&b.sleep_spots!==null&&b.sleep_spots>0&&!isSuppressed('buildings',b.gameobject_id)))}
function houseSpots(b){const hs=(DM?.houses?.records||[]).filter(h=>h.root===b.internal_name);return {baby:hs.filter(h=>h.accept_only_babies).reduce((n,h)=>n+h.sleep_spots,0),pet:hs.filter(h=>/pet house/i.test(h.path)).reduce((n,h)=>n+h.sleep_spots,0)}}
function buildingBiomes(b){return N.biomes.filter(n=>[b,...(b.variants||[])].some(v=>biomeRefers(n.placeables,v)))}
function levelsBuilding(b){const ids=new Set([b,...(b.variants||[])].map(v=>v.gameobject_id));return W.levels.filter(l=>l.scenario?.buildable_entries.some(x=>ids.has(x.gameobject_id)))}
function costText(b){const m=b.construction?.material_inputs||[];return m.length?inlineAmounts(m):'<span class="unknown">not recovered</span>'}
function costPerVillager(b){const m=b.construction?.material_inputs||[];if(!m.length||!b.sleep_spots)return '—';return m.map(x=>`${fmt(Math.round(100*x.count/b.sleep_spots)/100)} ${esc(x.name)}`).join(' + ')}
function housesPage(){const hs=houseList().sort((a,b)=>b.sleep_spots-a.sleep_spots||a.name.localeCompare(b.name)),rep=DM?.reproduction?.record,anyBaby=hs.some(h=>houseSpots(h).baby),anyPet=hs.some(h=>houseSpots(h).pet);
 const rows=hs.map(b=>{const sp=houseSpots(b),lv=levelsBuilding(b),bi=buildingBiomes(b);return `<tr><td>${icon('buildings',b)}<a href="${url('buildings',b.gameobject_id)}">${esc(b.name)}</a>${b.variants?.length>1?` <span class="objective-note">(${b.variants.length} versions)</span>`:''}</td><td>${fmt(b.sleep_spots)}</td><td>${sp.baby?fmt(sp.baby):'—'}</td><td>${sp.pet?fmt(sp.pet):'—'}</td><td>${b.dimensions?`${b.dimensions.x} × ${b.dimensions.z}`:'—'}</td><td>${costText(b)}</td><td>${costPerVillager(b)}</td><td>${heatRow(b)?'Yes':'—'}</td><td>${bi.length?bi.map(biomeLink).join(', '):'—'}</td><td>${lv.length?`<a href="${url('buildings',b.gameobject_id)}#level-availability">${lv.length}</a>`:'—'}</td></tr>`}).join('');
 return `${header('Houses','Every house compared: how many villagers sleep there, the baby and pet spots beside them, what it costs per villager, and where it can be built. Spot counts and costs are stored settings; who may share a house has not been tested.','MECHANICS')}<div class="table-wrap"><table><thead><tr><th scope="col">House</th><th scope="col">Villagers</th><th scope="col">Crib</th><th scope="col">Doghouse</th><th scope="col">Footprint</th><th scope="col">Cost</th><th scope="col">Cost per villager</th><th scope="col">Heated</th><th scope="col">Sandbox biomes</th><th scope="col">Levels</th></tr></thead><tbody>${rows}</tbody></table></div><section class="rule-section"><h2>How the spots work</h2><p>A house's villager spots are its sleeping places; the game counts a house as full when they are taken. ${anyBaby?'Each house also has one <strong>crib</strong> (a one-sleeper that accepts only babies): a newborn sleeps there, not in a villager spot, until it becomes a kid at age 3. ':''}${anyPet?'Each also has a one-sleeper <strong>doghouse</strong> that accepts no villagers; the files hold Dog Adult and Dog Baby prefabs with a hide-in-kennel activity, but when a dog appears in play is not recorded. ':''}Whether kids and elders count against the same spots as adults, and whether a family can split across houses, has not been tested.</p>${rep?`<h3>Why spare houses matter</h3><p>Births are checked against the stored reproduction values: a base chance of ${fmt(rep.BaseChance*100)}% per check for every ${plural(rep.AdultsPerCheck,'adult')}, raised by happiness (×${fmt(rep.HappinessMultiplier)} of it) and lowered by ${fmt(Math.abs(rep.ChildPerAdultMultiplier)*100)}% per child already per adult. <strong>With no free housing the chance is multiplied by ${fmt(1+rep.NoFreeHousingMultiplier)}</strong>, so a settlement with full houses all but stops having babies. Players find that building as many houses as possible is the surest way to get babies, and the data fits that: every house has exactly one crib, a baby occupies it until age 3, so the number of houses caps how many babies can be around at once, and "free housing" is most likely counted in free cribs. Population is capped at ${fmt(rep.PopulationLimit)}. How often the check runs is not stored. This is a reading of the stored values, not a tested rule.</p>`:''}<p class="small">Spots from each house prefab's sleeping places and attached baby and pet houses; costs from the linked construction formulas; biomes from the sandbox build lists; the reproduction values from the shared villager settings. See the <a href="${url('needs')}#need-housing">Housing</a> section on the Needs page and each house's own page for its evidence.</p></section>`}
const FOOD_BURN=()=>{const f=(DM?.needs?.records||[]).find(x=>x.need==='Food');return f?f.DailyRequired/f.UnitValue:null};
function foodPerDay(b){const kind=plantKind(b);if(kind==='crop'){const p=profileFor(b),g=growthFor(b);if(!p?.yield?.length||!g?.total_configured_stage_days)return null;const units=p.yield.reduce((a,y)=>a+y.count*(R[y.resource_id]?.need_units?.FoodUnits||0),0);if(!units)return null;return {units:units/g.total_configured_stage_days,how:`${p.yield.map(y=>`${fmt(y.count)} ${esc(R[y.resource_id]?.name||y.name)}`).join(' + ')} per ${plural(g.total_configured_stage_days,'day')}`,per:'full field'}}const fs=fruitSpawners(b).filter(sp=>sp.r.need_units?.FoodUnits>0);if(!fs.length)return null;const units=fs.reduce((a,sp)=>a+fruitRate(sp)*sp.r.need_units.FoodUnits,0);return {units,how:fs.map(sp=>`${fmt(Math.round(fruitRate(sp)*100)/100)} ${esc(sp.r.name)} a day`).join(' + '),per:'tree'}}
function villagersFed(units){const burn=FOOD_BURN();return burn?units/burn:null}
function feedsText(b){const f=foodPerDay(b),v=f?villagersFed(f.units):null;if(!f||v===null)return null;return `about ${fmt(Math.round(v*100)/100)} villager${Math.round(v*100)/100===1?'':'s'} from one ${f.per} <span class="objective-note">(${f.how} = ${fmt(Math.round(f.units*100)/100)} food units a day; a villager burns ${fmt(Math.round(FOOD_BURN()*100)/100)})</span>`}
function feedsCell(b){const f=foodPerDay(b),v=f?villagersFed(f.units):null;return v===null?'—':`${fmt(Math.round(v*100)/100)} villager${Math.round(v*100)/100===1?'':'s'}`}
function foodSourcesSection(){const plants=uniq(D.buildings.filter(b=>b.is_plant&&!isSuppressed('buildings',b.gameobject_id))).map(b=>({b,f:foodPerDay(b)})).filter(x=>x.f).map(x=>({...x,v:villagersFed(x.f.units)})).sort((a,b)=>b.v-a.v);if(!plants.length)return '';const burn=FOOD_BURN();return `<section class="rule-section" id="food-sources"><h2>How much each source feeds</h2><p>Food units a day from one full field or one tree, read as villagers fed, using the stored yields, growth days and fruit intervals and the ${fmt(Math.round(burn*100)/100)} food units a villager burns a day. Processed foods (bread, cookies, cheese) depend on factory speed, which is not stored, so they are not ranked here. Real figures are lower: fruit waits to be picked, fields idle between harvests, and rich foods eaten early are partly wasted.</p><div class="table-wrap"><table><thead><tr><th scope="col">Source</th><th scope="col">Kind</th><th scope="col">Yield</th><th scope="col">Food units a day</th><th scope="col">Villagers fed</th><th scope="col">Footprint</th><th scope="col">Tended by</th></tr></thead><tbody>${plants.map(({b,f,v})=>`<tr><td>${icon('buildings',b)}<a href="${url('buildings',b.gameobject_id)}">${esc(b.name)}</a></td><td>${PLANT_GROUPS[plantGroup(b)]}</td><td>${f.how}</td><td>${fmt(Math.round(f.units*100)/100)}</td><td>${fmt(Math.round(v*100)/100)}</td><td>${b.dimensions?`${b.dimensions.x} × ${b.dimensions.z}`:'—'}</td><td>${plantedBy(b)}</td></tr>`).join('')}</tbody></table></div></section>`}
function needModelSection(){const recs=DM?.needs?.records||[];if(!recs.length)return '';const order=['Food','Hydration','Heat','Energy','Entertainment','Wellness','Community','Refreshment'],rows=recs.slice().sort((a,b)=>order.indexOf(a.need)-order.indexOf(b.need));
 return `<section class="rule-section" id="need-model"><h2>How the meters work</h2><p>Each need is a meter. It starts at the first value, falls by the daily amount, and every unit on a food, drink or other item restores the “one unit” amount. Below the low warning villagers complain; above the content line the need counts as met; the meter cannot rise past its highest value. Three needs can kill: Food (hunger) at −100, Heat (cold) and Hydration (thirst) at −50. These are the stored settings; nobody has timed them in play yet.</p><div class="table-wrap"><table><thead><tr><th>Need</th><th>Starts at</th><th>Falls per day</th><th>One unit restores</th><th>Low warning</th><th>Content above</th><th>Full at</th><th>Highest</th><th>Death at</th></tr></thead><tbody>${rows.map(n=>`<tr><td><a href="#need-${slug(needLabel(n.need))}">${esc(needLabel(n.need))}</a></td><td>${fmt(n.InitialValue)}</td><td>${fmt(n.DailyRequired)}</td><td>${fmt(n.UnitValue)}</td><td>${n.HasLowValue?fmt(n.LowThreshold):'—'}</td><td>${fmt(n.SatisfactionThreshold)}</td><td>${fmt(n.FullnessThreshold)}</td><td>${fmt(n.MaxValue)}</td><td>${n.HasDeathValue?`${fmt(n.DeathValue)} (${esc(n.death_reason==='OldAge'?'old age':n.death_reason.toLowerCase())})`:'—'}</td></tr>`).join('')}</tbody></table></div><p>If the numbers behave as named, a villager uses about ${fmt(Math.round(100*40/60)/100)} food units a day (40 lost, 60 restored per unit), and ${fmt(20/25)} drink units and ${fmt(20/25)} heat units where those needs are switched on. ${(()=>{const bread=D.resources.find(r=>r.name==='Bread'&&r.publicly_named);if(!bread||!bread.need_units.FoodUnits)return '';const u=bread.need_units.FoodUnits;return `A Bread carries ${fmt(u)} food unit${u===1?'':'s'}, so that is about ${fmt(Math.round(100*(40/60)/u)/100)} loaves a day per villager.`})()}</p></section>`}
function eatingSection(){const f=(DM?.needs?.records||[]).find(x=>x.need==='Food'),e=DM?.eating;if(!f||!e)return '';const d=f.DailyRequired,days=v=>fmt(Math.round(100*(f.MaxValue-v)/d)/100),STATUS={CriticallyCloseToDeath:'Critical',Low:'Low',Wanting:'Wanting',Satisfied:'Satisfied',Full:'Full'},band={Full:`${fmt(f.FullnessThreshold)} and above`,Satisfied:`${fmt(f.SatisfactionThreshold)}–${fmt(f.FullnessThreshold)}`,Wanting:`${fmt(f.LowThreshold)}–${fmt(f.SatisfactionThreshold)}`,Low:`below ${fmt(f.LowThreshold)}`,CriticallyCloseToDeath:`near ${fmt(f.DeathValue)}`};
 const foods=needSatisfiers('FoodUnits'),rate=u=>Math.round(100*d/(u*f.UnitValue))/100;
 return `<section class="rule-section" id="eating"><h2>How eating works</h2><p>Villagers do not eat on a schedule. The Food meter starts a new villager at ${fmt(f.InitialValue)} and tops out at ${fmt(f.MaxValue)}; it falls ${fmt(d)} a day. From full, a villager stays Full for ${days(f.FullnessThreshold)} day${days(f.FullnessThreshold)==='1'?'':'s'}, counts as Satisfied until day ${days(f.SatisfactionThreshold)}, is merely Wanting until day ${days(f.LowThreshold)}, then Low, and starves only after about ${days(f.DeathValue)} days with nothing at all. Hunger is a slow slide, so a short gap in bread does no harm.</p><h3>When they choose to eat</h3><p>Eating competes with work, sleep and play. The game scales the urge to eat by how hungry the villager is; a Full villager never eats, a Satisfied one eats only when little else calls, a hungry one drops almost everything.</p><div class="table-wrap"><table><thead><tr><th scope="col">Hunger status</th><th scope="col">Meter (as we read the bands)</th><th scope="col">Urge to eat (0–1)</th></tr></thead><tbody>${e.status_multipliers.slice().reverse().map(m=>`<tr><td>${STATUS[m.status]||esc(m.status)}</td><td>${band[m.status]||'—'}</td><td>${m.food===0?'0 (never)':fmt(m.food)}</td></tr>`).join('')}</tbody></table></div><p class="small">Stored on every villager as the eat activity’s priority (base ${fmt(e.eat_alone.base_importance)}, times the row above). Eating at a kitchen or other eating place starts a touch higher (${fmt(e.eat_at_social_spot.base_importance)}), so a villager with both options slightly prefers company. No stored field expresses a liking for particular dishes; if villagers favour one food over another beyond its units, that lives in code.</p><h3>What one meal is worth</h3><p>Each food unit restores ${fmt(f.UnitValue)} on the meter, but the meter cannot pass ${fmt(f.MaxValue)}. A rich food eaten by a barely hungry villager wastes part of its value: a ${fmt(2)}-unit Bread eaten at Satisfied (${fmt(f.SatisfactionThreshold)}) can only add ${fmt(f.MaxValue-f.SatisfactionThreshold)} of its ${fmt(2*f.UnitValue)}. The “worth it below” column is the meter value under which the whole item counts.</p><div class="table-wrap"><table><thead><tr><th scope="col">Food</th><th scope="col">Units</th><th scope="col">Restores</th><th scope="col">Worth it below</th><th scope="col">Per villager per day (no waste)</th></tr></thead><tbody>${foods.map(r=>{const u=r.need_units.FoodUnits,v=u*f.UnitValue;return `<tr><td><a href="${url('resources',r.id)}">${esc(r.name)}</a></td><td>${fmt(u)}</td><td>${fmt(v)}</td><td>${fmt(f.MaxValue-v)}${f.MaxValue-v<f.LowThreshold?' <span class="objective-note">(only when Low)</span>':''}</td><td>${fmt(rate(u))}</td></tr>`}).join('')}</tbody></table></div><p>Long run a villager burns ${fmt(d)} a day, so the last column is ${fmt(d)} divided by what the item restores. Real use sits above it because of cap waste and because villagers often eat before they are Low. For a settlement, multiply by villagers and add a margin. The <a href="${url('food')}#food-sources">Food</a> page turns this round and says how many villagers one field or tree feeds.</p><p class="small">All figures are stored settings read as named; none has been timed in play. The decisive test is to watch one villager for five game days and log every meal with the meter value, the item and the place.</p></section>`}
function villagerLifeSection(){const life=DM?.life_stages?.records||[],v=life.find(x=>x.path==='Villager Adult'),l=life.find(x=>x.path==='_Leader Base'),rep=DM?.reproduction?.record;if(!v)return '';const a=v.stage_ages;
 return `<section class="rule-section" id="villager-life"><h2>Villager life</h2><p>Villagers age in days. A baby becomes a kid at ${a.KidAge}, an adult at ${a.AdultAge} and an elder at ${a.ElderAge}, and dies of old age somewhere between ${v.old_age_death_min} and ${v.old_age_death_max} days old (villagers already present when a map starts can be at most ${v.old_age_initial_max}).${l?` Leaders arrive as adults from age ${l.stage_ages.AdultAge} and skip childhood.`:''} Animals are quicker: cows and sheep live about 7 days, chickens ${life.find(x=>x.path==='Chicken Adult')?.old_age_death_min}–${life.find(x=>x.path==='Chicken Adult')?.old_age_death_max}.</p>${rep?`<h3>New babies</h3><p>The game checks each pair of adults with a base chance of ${fmt(Math.round(rep.BaseChance*1000)/10)}% per check. Stored adjustments: no free housing ${fmt(Math.round(rep.NoFreeHousingMultiplier*1000)/10)}%, happiness up to +${fmt(Math.round(rep.HappinessMultiplier*1000)/10)}%, and ${fmt(Math.round(Math.abs(rep.ChildPerAdultMultiplier)*1000)/10)}% less for every child per adult already in the village. Population stops at ${rep.PopulationLimit}. How often the check runs is not stored here.</p>`:''}</section>`}
function concernEffectsSection(){const recs=DM?.concerns?.records||[];if(!recs.length)return '';const words=e=>{const out=[];if(e.CarrySpeedMultiplier&&e.CarrySpeedMultiplier!==1)out.push(`carry speed ×${fmt(e.CarrySpeedMultiplier)}`);if(e.WalkSpeedMultiplier&&e.WalkSpeedMultiplier!==1)out.push(`walking speed ×${fmt(e.WalkSpeedMultiplier)}`);if(e.SleepDurationMultiplier&&e.SleepDurationMultiplier!==1)out.push(`sleep ${fmt(Math.round((1-e.SleepDurationMultiplier)*100))}% shorter`);if(e.ReproductionMultiplier&&e.ReproductionMultiplier!==1)out.push(`baby chance ×${fmt(e.ReproductionMultiplier)}`);if(e.LifespanIncreasedByDay)out.push(`lifespan +${fmt(e.LifespanIncreasedByDay)} day per day`);if(e.NeedMultipliers?.length){const m=e.NeedMultipliers;out.push(`${m.map(x=>needLabel(x.need)).join(', ')} fall ${fmt(Math.round((1-m[0].multiplier)*100))}% slower`)}return out.join('; ')||'—'};
 return `<section class="rule-section" id="concern-effects"><h2>What keeping villagers content does</h2><p>Each need the level switches on counts towards happiness with a stored weight, and a villager whose need is met gets a bonus.</p><div class="table-wrap"><table><thead><tr><th>Need</th><th>Weight</th><th>Bonus when met</th></tr></thead><tbody>${recs.slice().sort((a,b)=>b.weight-a.weight).map(c=>`<tr><td>${esc({Nutrition:'Food',Housing:'Housing',Entertainment:'Fun',Refreshment:'Cooling'}[c.concern]||c.concern)}</td><td>${fmt(c.weight)}</td><td>${words(c.satisfied_effect)}</td></tr>`).join('')}</tbody></table></div></section>`}
function weatherSection(o){const groups=(DM?.level_events?.groups||[]).filter(g=>o.id==='Tropical'&&/tropical/i.test(g.path));if(!groups.length)return '';const events=DM.level_events.records;const g=groups[0],members=g.members.map(m=>events.find(e=>e.path===m)).filter(Boolean);const describe=e=>{const m=e.effect.NeedMultipliers?.[0];if(!m)return '';return m.multiplier<0?`the ${needLabel(m.need)} meter refills at ${fmt(Math.abs(m.multiplier))}× its normal fall rate`:`the ${needLabel(m.need)} meter falls ${fmt(m.multiplier)}× as fast`};
 return `<section class="rule-section" id="weather"><h2>Weather</h2><p>Every ${fmt(g.min_period_days)} to ${fmt(g.max_period_days)} days one of these events starts, announced ${fmt(members[0]?.notification_days_before||0)} days ahead:</p><ul>${members.map(e=>`<li><strong>${esc(e.path.split('/').pop())}</strong>: for ${plural(e.duration_days,'day')}, ${describe(e)}.</li>`).join('')}</ul></section>`}
function boostsSection(){const recs=DM?.tournament_boosts?.records||[];if(!recs.length)return '';const line=b=>b.class==='NeedBoostAction'?`${esc(needLabel(b.need))} falls ${fmt(Math.round((1-b.DrainMultiplier)*100))}% slower`:b.class==='GrowthBoostAction'?`crops grow in ${fmt(b.Multiplier)}× the time`:b.class==='ReproductionBoostAction'?`baby chance ×${fmt(b.Multiplier)}`:b.class==='SpeedBoostAction'?`villagers move faster${b.Multiplier?` (×${fmt(b.Multiplier)})`:''}`:{ChildGrowthBoostAction:'children grow up twice as fast',FreeBuildAction:'build for free',InstaBuildAction:'finish a construction at once',ResourceBundleAction:'a bundle of resources',SpawnVillagerAction:'a new villager arrives'}[b.class]||b.class;
 return `<section class="rule-section" id="boosts"><h2>Boosts</h2><p>Tournament actions stored in the game files (their costs and how long they last are not stored with them):</p><ul>${recs.map(b=>`<li><strong>${esc(b.path)}</strong>: ${line(b)}</li>`).join('')}</ul></section>`}
function pilesResearch(b){const piles=pilesFor(b);if(!piles.length)return '';return `<section class="rule-section"><h2>Piles</h2><p>Every pile this building prefab defines, from the decoded <code>ResourcePileBehaviour</code> records. Public output piles are what the stockpile and other buildings can take from; the rest hold work in progress. The game stops a workspot when its output piles are full; which piles count as full for a given step is not stored here.</p><div class="table-wrap"><table><thead><tr><th>Pile</th><th>Holds</th><th>Capacity</th><th>Kind</th><th>Height</th></tr></thead><tbody>${piles.map(p=>{const r=pileResource(p);return `<tr><td>${esc(p.path.split('/').slice(1).join('/'))}</td><td>${r?`<a class="resource-link" href="${url('resources',r.id)}">${esc(r.name)}</a>`:p.reference_resource?esc(p.reference_resource):'<span class="unknown">set by the workspot</span>'}</td><td>${p.capacity}</td><td>${p.public_output?'public output':p.available_to_store?'storage':'work in progress'}</td><td>${esc(p.pile_height.toLowerCase())}</td></tr>`}).join('')}</tbody></table></div></section>`}
function buildingInfobox(b){const cat=category(b),recipe=b.derived_recipes.find(r=>!r.caveats.length),cycle=cycleRecipe(b),cap=b.gameplay?.output_capacity,guide=W.ui_observations?.buildings?.[b.name],maps=W.levels.filter(l=>l.scenario?.buildable_entries.some(x=>x.gameobject_id===b.gameobject_id)),growth=growthFor(b);
 const plantKind=b.paths.some(p=>p.includes('/orchard/'))?'Orchard plant':b.paths.some(p=>p.includes('/forester/'))?'Forestry plant':'Field crop';
 if(b.is_plant)return infobox('buildings',b,[['Type',PLANT_GROUPS[plantGroup(b)]],['Yields',mainYield(b)||plantYield(b)],['Also',alsoYield(b)],['Rate',rateText(b)],['Planted by',plantedBy(b)],['Harvested by',harvestedBy(b)],['Biomes',biomesRow(b)],['Grows wild',wildRow(b)],['Spreads',spreadText(b)],['Feeds',feedsText(b)],['Grows in',growthText(b)],['Levels',maps.length?`<a href="#level-availability">${maps.length} level${maps.length>1?'s':''}</a>`:null]],icon('buildings',b));
 return infobox('buildings',b,[['Type',CATEGORY_LABELS[cat]],['Footprint',!b.is_plant&&b.dimensions?`${fmt(b.dimensions.x)} × ${fmt(b.dimensions.z)}`:null],['Cost',!b.is_plant&&b.construction?.material_inputs.length?inlineAmounts(b.construction.material_inputs):null],['Workers',b.max_workers],['Houses',housingRow(b)],['Work hours',shiftRow(b)],['Harvests from',harvestRow(b)],['Visiting gives',socialRow(b)],['Reported output',reportedRateRow(b)],['Placement',placementRow(b)],['Recipe',cycle?`${inlineAmounts(cycle.inputs)} → ${inlineAmounts(cycle.outputs)} <span class="objective-note">${recipeLabel(cycle)}</span>`:b.formula_ids.length?`<a href="${url('chains',b.gameobject_id)}">See production chain</a>`:null],['Capacity',capacityRow(b)],['Heating',heatRow(b)],['Added in',addedIn(b.internal_name)],['Growth',growth?`${growth.total_configured_stage_days} day${growth.total_configured_stage_days===1?'':'s'} across ${growth.stages.length} stage${growth.stages.length===1?'':'s'} <span class="objective-note">stored durations, not timed in play</span>`:null],['Levels',maps.length?`<a href="#level-availability">${maps.length} level${maps.length>1?'s':''}</a>`:null]],icon('buildings',b))}
function resourceInfobox(r,producing,using,costs,objectives){const vals=Object.entries(r.need_units).filter(([,v])=>v!==0);const list=bs=>uniq(bs).slice(0,6).map(b=>`<a href="${url('buildings',b.gameobject_id)}">${esc(b.name)}</a>`).join(', ')+(uniq(bs).length>6?` and ${uniq(bs).length-6} more`:'');
 return infobox('resources',r,[['Type',r.publicly_named?(r.need_units.FoodUnits>0?'Food':'Resource'):'Intermediate'],['Satisfies',(vals.length||resourceStatedEffects(r).length)?[...vals.map(([k,v])=>`<a href="${url('needs')}#need-${slug(k==='EntertainmentUnits'?'Fun':k==='RefreshmentUnits'?'Cooling':k.replace('Units',''))}">${esc(k==='EntertainmentUnits'?'Fun':k==='RefreshmentUnits'?'Cooling':k.replace('Units',''))}</a> ${fmt(v)}`),...resourceStatedEffects(r).map(e=>{const v=socialNeedValue(e.building,e.need);return `<a href="${url('needs')}#need-${slug(e.need)}">${esc(e.need)}</a> ${v!==null?fmt(v)+' <span class="objective-note">(at the '+esc(e.building.name)+')</span>':'<span class="objective-note">(stated, amount unknown)</span>'}`})].join(', '):null],['Consumed by',adultsOnly(r)?'Adults only':null],['Gear effect',gearRow(r)],['Made from',r.made_from?.length?r.made_from.map(m=>`${perUnitText(m.per_unit,r.name)} <span class="objective-note">(each, at the ${esc(m.building_name)})</span>`).join('<br>'):null],['Produced by',producing.length?list(producing):null],['Used by',using.length?list(using):null],['Builds',costs.length?list(costs):null],['Added in',addedIn(r.internal_name)],['Objectives',objectives.length?`<a href="#objective-backlinks">${objectives.length} level${objectives.length>1?'s':''}</a>`:null]],icon('resources',r))}
function verifyBadge(type,id,extra=''){return `<p class="verify-badge"><span>Game data v30 · build 254</span>${extra}<a href="${url('evidence',type+'/'+id)}">Sources &amp; research notes</a></p>`}
function contributionLinks(type,id,name){const file=contentFile(type,id);if(!file)return '';const spoiler=!!spoilerEntry(type,id);const title=encodeURIComponent(spoiler?'Correction for a spoiler entry':`Correction: ${name}`);const page=spoiler?'':`&amp;page=${encodeURIComponent(name)}`;return `<p class="article-actions"><a href="${GITHUB}/edit/main/${file}">Suggest an edit</a><a href="${GITHUB}/issues/new?template=content-correction.yml&amp;title=${title}${page}">Report a problem</a><a href="${GITHUB}/blob/main/CONTRIBUTING.md">How contributions work</a></p>`}
function observationLink(type,id,name){const spoiler=!!spoilerEntry(type,id);const title=encodeURIComponent(spoiler?'Observation about a spoiler entry':`Observation: ${name}`);return `<p class="article-actions"><a href="${GITHUB}/issues/new?template=gameplay-observation.yml&amp;title=${title}${spoiler?'':`&amp;target=${encodeURIComponent(name)}`}">Report a gameplay observation</a><a href="${GITHUB}/blob/main/CONTRIBUTING.md#evidence-and-uncertainty">What counts as evidence</a></p>`}
function navboxList(label,items,type){return items.length?`<div class="navbox-row"><span class="navbox-label">${label}</span><ul>${items.map(o=>`<li><a href="${url(type,o.gameobject_id||o.id)}">${esc(o.name)}</a></li>`).join('')}</ul></div>`:''}
function navbox(type,o){const sorted=xs=>[...xs].sort((a,b)=>a.name.localeCompare(b.name));let title='',rows='';
 if(type==='buildings'||type==='chains'){const cat=category(o);const same=uniq(D.buildings.filter(b=>!isSuppressed('buildings',b.gameobject_id)&&!b.is_plant&&category(b)===cat));title=CATEGORY_LABELS[cat]+'s';if(o.is_plant){const plants=uniq(D.buildings.filter(b=>b.is_plant&&!isSuppressed('buildings',b.gameobject_id)&&b.name!=='Template'));title='Fields & plants';title='Plants';rows=navboxList('Field crops',sorted(plants.filter(p=>plantGroup(p)==='crop')),'buildings')+navboxList('Fruit trees',sorted(plants.filter(p=>plantGroup(p)==='orchard')),'buildings')+navboxList('Forestry',sorted(plants.filter(p=>plantGroup(p)==='forestry')),'buildings')+navboxList('Decorative',sorted(plants.filter(p=>plantGroup(p)==='decorative')),'buildings')}else rows=navboxList(title,sorted(same),'buildings')}
 if(type==='resources'){const food=o.publicly_named&&o.need_units.FoodUnits>0;const items=uniq(D.resources.filter(r=>r.publicly_named&&(food?r.need_units.FoodUnits>0:r.need_units.FoodUnits===0)));title=food?'Food':'Resources';rows=navboxList(title,sorted(items),'resources')}
 if(type==='heroes'){title='Leaders';rows=navboxList('Leaders',sorted(W.leaders),'heroes')}
 if(type==='biomes'){title='Biomes';rows=navboxList('Biomes',sorted(W.biomes),'biomes')}
 if(type==='levels'){const s=storyOf(o.id),c=campaignOf(o.id);if(s&&c){title=esc(c.name);rows=navboxList(esc(s.name),s.level_ids.map(i=>W.levels.find(l=>l.id===i)).filter(Boolean),'levels');const others=W.stories.filter(x=>x.campaign_id===c.id&&x!==s).sort((a,b)=>a.menu_order-b.menu_order);rows+=others.length?`<div class="navbox-row"><span class="navbox-label">Other stories</span><ul>${others.map(x=>`<li><a href="${url('campaigns',c.id)}">${esc(x.name)}</a></li>`).join('')}</ul></div>`:''}}
 return rows?`<nav class="navbox" aria-label="Related pages"><h2>${title}</h2>${rows}</nav>`:''}
function storyContext(o){const s=storyOf(o.id),c=campaignOf(o.id);if(!s||!c)return o.category==='tournament_tutorial'?'<p class="story-context">Tournament tutorial level.</p>':'';const ids=s.level_ids,pos=ids.indexOf(o.id),prev=pos>0?W.levels.find(l=>l.id===ids[pos-1]):null,next=pos<ids.length-1?W.levels.find(l=>l.id===ids[pos+1]):null,leader=W.leaders.find(l=>l.name===s.leader_name);
 return `<div class="story-context"><p><a href="${url('campaigns',c.id)}">${esc(c.name)}</a> › <strong>${esc(s.name)}</strong> · Level ${pos+1} of ${ids.length}${leader?` · Leader: <a href="${url('heroes',leader.id)}">${esc(leader.name)}</a>`:''}</p><p class="story-nav">${prev?`<a href="${url('levels',prev.id)}">← ${esc(prev.name)}</a>`:'<span></span>'}${next?`<a href="${url('levels',next.id)}">${esc(next.name)} →</a>`:''}</p></div>`}
function leaderStories(o){const stories=W.stories.filter(s=>s.leader_name===o.name&&s.level_ids?.length).sort((a,b)=>a.campaign_id.localeCompare(b.campaign_id)||a.menu_order-b.menu_order);if(!stories.length)return '';return `<section class="rule-section"><h2>Stories &amp; levels</h2>${stories.map(s=>{const c=W.campaigns.find(c=>c.id===s.campaign_id);return `<h3>${esc(s.name)}${c?` <small class="small"><a href="${url('campaigns',c.id)}">${esc(c.name)}</a></small>`:''}</h3><ol class="story-levels">${s.level_ids.map(i=>W.levels.find(l=>l.id===i)).filter(Boolean).map(l=>`<li>${levelLink(l)}${l.scenario?` <span class="objective-note">${l.scenario.primary_objective_count} main objective${l.scenario.primary_objective_count===1?'':'s'}${l.scenario.day_limit>0?` · ${l.scenario.day_limit} days`:''}</span>`:''}</li>`).join('')}</ol>`}).join('')}</section>`}

// Work schedules: WorkplaceConfig.WorkTimeRange stores a start and end as fractions of a day (wrapping past 1.0). Most workplaces use 0.9 → 0.5; differences are reported relative to that standard shift. The clock mapping of 0.0 is unresolved.
const STANDARD_SHIFT={start:0.9,end:0.5};
function shiftLength(s,e){const l=((e-s)%1+1)%1;return l||1}
function shiftInfo(b){const r=b.workplace_config?.WorkTimeRange;if(!r)return null;const s=+r.Start.toFixed(3),e=+r.End.toFixed(3),off=v=>+((((v+0.5)%1)+1)%1-0.5).toFixed(3),startOff=off(s-STANDARD_SHIFT.start),endOff=off(e-STANDARD_SHIFT.end),length=shiftLength(s,e);
 const amount=v=>{const a=Math.abs(v);return a===0.1?'a tenth of a day':a===0.05?'a twentieth of a day':`${fmt(a)} of a day`};const parts=[];
 if(startOff>0)parts.push(`starts ${amount(startOff)} later`);if(startOff<0)parts.push(`starts ${amount(startOff)} earlier`);if(endOff>0)parts.push(`finishes ${amount(endOff)} later`);if(endOff<0)parts.push(`finishes ${amount(endOff)} earlier`);
 return {start:s,end:e,length,startOff,endOff,standard:!parts.length,label:parts.length?parts.join(', '):'Standard hours'}}
function shiftRow(b){const i=shiftInfo(b);return i?`${esc(i.label)} <span class="objective-note">${fmt(Math.round(i.length*100))}% of the day</span>`:null}
function workSchedulesSection(){const groups=new Map();for(const b of uniq(D.buildings.filter(b=>b.workplace_config&&!isSuppressed('buildings',b.gameobject_id)))){const i=shiftInfo(b),k=`${i.start}→${i.end}`;if(!groups.has(k))groups.set(k,{info:i,buildings:[]});groups.get(k).buildings.push(b)}
 const rows=[...groups.values()].sort((a,b)=>b.buildings.length-a.buildings.length).map(g=>`<tr><td>${fmt(g.info.start)} → ${fmt(g.info.end)}</td><td>${esc(g.info.label)}</td><td>${fmt(Math.round(g.info.length*100))}%</td><td>${g.buildings.sort((a,b)=>a.name.localeCompare(b.name)).map(b=>`<a href="${url('buildings',b.gameobject_id)}">${esc(b.name)}</a>`).join(', ')}</td></tr>`).join('');
 return `<section class="rule-section" id="work-schedules"><h2>Work schedules</h2><p>The in-game clock dial shows a day face for the first half of each cycle and a night face for the second half, and the game names no hours. The standard crew therefore starts a tenth of a day before the dial turns to day and stops when it turns to night; the Clay Pit crew starts as the dial turns to day and works a tenth of a day into the night. One cycle is 300 seconds at normal speed, so a tenth of a day is 30 seconds.</p><p>Each workplace stores a shift as a start and end fraction of the day. A game day is ${fmt(RF.seconds_per_day)} simulation seconds at normal speed, so the standard shift lasts ${fmt(Math.round(RF.seconds_per_day*0.6))} seconds and a tenth of a day is ${fmt(RF.seconds_per_day/10)} seconds. Most workplaces run the same standard shift; a few start or finish later, which is why some crews are seen leaving for work after everyone else. Which clock hour the fraction 0 corresponds to has not been established.</p><div class="table-wrap"><table><thead><tr><th scope="col">Stored shift</th><th scope="col">Compared with the standard shift</th><th scope="col">Share of the day</th><th scope="col">Workplaces</th></tr></thead><tbody>${rows}</tbody></table></div></section>`}

// Level strategies: community advice stored in content/strategies/<levelId>.json, contributed through the level-strategy issue form and rendered apart from decoded facts.
function strategyFormUrl(o){const spoiler=!!spoilerEntry('levels',o.id);const title=encodeURIComponent(spoiler?'Strategy for a spoiler level':`Strategy: ${o.name}`);return `${GITHUB}/issues/new?template=level-strategy.yml&amp;title=${title}${spoiler?'':`&amp;level=${encodeURIComponent(o.name)}`}`}
const LINK_TYPES={guide:'Written guides',walkthrough:'Walkthroughs',video:'Videos and channels',community:'Communities',official:'Official',tool:'Tools'};
function linkFormUrl(level){return `${GITHUB}/issues/new?template=external-link.yml${level?`&amp;levels=${encodeURIComponent(level.name)}`:''}`}
function outLink(e){return `<a href="${esc(e.url)}" rel="nofollow noopener" target="_blank">${esc(e.title)}</a>`}
function linksForLevel(o){return (W.links||[]).filter(e=>(e.levels||[]).some(x=>x===o.id||x===o.name))}
function guidesPage(){const links=W.links||[],groups=Object.entries(LINK_TYPES).map(([t,label])=>[label,links.filter(e=>e.type===t)]).filter(([,xs])=>xs.length);
 return `${header('Guides elsewhere','Strategy guides, walkthroughs, videos and communities for Outlanders 2 that live on other sites. These are pointers, not sources: nothing here is cited for a decoded fact, and the wiki does not vouch for advice that has not been checked against the data.','COMMUNITY')}<p class="article-actions"><a href="${linkFormUrl()}">Suggest a link</a><a href="${GITHUB}/blob/main/CONTRIBUTING.md#suggest-a-link">How links are reviewed</a></p>${links.length?groups.map(([label,xs])=>`<section class="rule-section"><h2>${esc(label)}</h2><div class="table-wrap"><table><thead><tr><th scope="col">Link</th><th scope="col">Site</th><th scope="col">Covers</th><th scope="col">Note</th><th scope="col">Checked</th></tr></thead><tbody>${xs.map(e=>`<tr><td>${outLink(e)}${e.status==='needs-check'?' <span class="tag amber">not yet reviewed</span>':''}</td><td>${esc(e.site)}${e.language&&e.language!=='en'?` <span class="objective-note">(${esc(e.language)})</span>`:''}</td><td>${(e.covers||[]).map(esc).join(', ')||'—'}${e.levels?.length?`<br><span class="objective-note">${e.levels.map(id=>{const l=W.levels.find(x=>x.id===id||x.name===id);return l?`<a href="${url('levels',l.id)}">${esc(l.name)}</a>`:esc(id)}).join(', ')}</span>`:''}</td><td>${esc(e.note)}</td><td>${esc(e.date_checked)}</td></tr>`).join('')}</tbody></table></div></section>`).join(''):'<p>No links recorded yet. Use the form above to suggest one.</p>'}<section class="rule-section"><h2>What belongs here</h2><p>Anything that helps someone play: level walkthroughs, build-order videos, calculators, active forums. Not copies of this wiki, paywalled pages, or sites that exist to carry adverts. A maintainer checks each suggestion once and marks it listed; the link checker revisits every URL weekly and a dead link is removed.</p></section>`}
function strategySection(o){const s=(W.strategies||[]).find(x=>x.id===o.id);const share=`<p class="article-actions"><a href="${strategyFormUrl(o)}">${s?'Suggest a change to this strategy':'Share a strategy for this level'}</a><a href="${GITHUB}/blob/main/CONTRIBUTING.md#share-a-level-strategy">How strategies are reviewed</a></p>`;
 const outs=linksForLevel(o),outsHtml=outs.length?`<p><strong>Elsewhere:</strong> ${outs.map(e=>`${outLink(e)} <span class="objective-note">(${esc(e.site)})</span>`).join(', ')} · <a href="${url('guides')}">all guides elsewhere</a></p>`:'';
 if(!s)return `<section class="rule-section strategy"><h2>Strategy</h2><p>No community strategy has been recorded for this level yet. If you have finished it, the form takes a build order, what to watch out for, and the game version; a maintainer turns it into a page section.</p>${outsHtml}${share}</section>`;
 const steps=s.build_order.map(step=>{const b=B[step.gameobject_id];return `<li>${b?`<a href="${url('buildings',b.gameobject_id)}">${esc(b.name)}</a>`:esc(step.name||'Unknown building')}${step.note?` <span class="objective-note">${esc(step.note)}</span>`:''}</li>`}).join('');
 return `<section class="rule-section strategy"><h2>Strategy <span class="tag ${s.status==='reviewed'?'':'amber'}">${s.status==='reviewed'?'Community · reviewed':'Community · draft'}</span></h2><p>${esc(s.summary)}</p>${steps?`<h3>Suggested build order</h3><ol class="story-levels">${steps}</ol>`:''}${s.pitfalls?.length?`<h3>Watch out for</h3><ul class="check-list">${s.pitfalls.map(p=>`<li>${esc(p)}</li>`).join('')}</ul>`:''}<p class="objective-note">Contributed by ${esc(s.contributor)} · game version ${esc(s.game_version)} · ${esc(s.date)}${s.source?` · ${esc(s.source)}`:''}. Community advice, not decoded data.</p>${outsHtml}${share}</section>`}

// Version history: content/history.json holds dated, evidenced changes per entity. Entries render as a History section on entity pages and as a site Changelog grouped by game version.
function historyEntries(type,id){return ((fullWorld||W).history?.entries||[]).filter(e=>e.type===type&&String(e.id)===String(id)).sort((a,b)=>b.date.localeCompare(a.date))}
function historySection(type,id){const rows=historyEntries(type,id);if(!rows.length)return '';return `<section class="rule-section history"><h2>History</h2><table class="history-table"><tbody>${rows.map(e=>`<tr><td><strong>Update ${esc(e.game_version)}</strong><br><span class="objective-note">${esc(e.date)}</span></td><td>${esc(e.change)} <span class="objective-note">${esc(e.evidence.kind.replace('-',' '))}${e.evidence.url?` · <a href="${esc(e.evidence.url)}">link</a>`:''}</span></td></tr>`).join('')}</tbody></table></section>`}
function historyTargetLink(e){const type=e.type;const list=type==='buildings'?D.buildings:type==='resources'?D.resources:type==='heroes'?W.leaders:W[type];const o=list?.find(x=>String(x.gameobject_id??x.id)===String(e.id));return o?`<a href="${url(type,e.id)}">${esc(o.name)}</a>`:null}
function changelogPage(){const h=W.history||{entries:[]};const visible=h.entries.filter(e=>!spoilerEntry(e.type,e.id)).map(e=>({...e,link:historyTargetLink(e)})).filter(e=>e.link);const groups=new Map();for(const e of visible){const k=e.game_version;if(!groups.has(k))groups.set(k,[]);groups.get(k).push(e)}
 const versions=[...groups.keys()].sort((a,b)=>(parseFloat(b)||0)-(parseFloat(a)||0));
 const wiki=(W.changelog||'').split('\n').filter(l=>!/^(What changed on the wiki|Every pull request adds)/.test(l)).join('\n');return `${header('Changelog','Two lists: what changed on this wiki, newest first, and what changed in each game update as far as the wiki can establish it. The current data baseline is version 30, build 254.','WIKI & VERSION HISTORY')}${wiki.trim()?`<section class="rule-section" id="wiki-changes"><h2>Wiki changes</h2><p class="small">One line per merged change, with the page to look at. Kept in <code>CHANGELOG.md</code>; reasoning and provenance are in <code>CONTENT-NOTES.md</code>.</p><div class="prose changelog">${mdBlocks(wiki,{h2:'h3'})}</div></section>`:''}<section class="rule-section" id="game-updates"><h2>Game updates</h2><p>${h.baseline?esc(h.baseline):''} Earlier updates are backdated only where an official source or decoded marker ties content to an update. Future builds are compared with <code>scripts/compare-content.mjs</code>, and reviewed differences are added here.</p>${versions.map(v=>{const rows=groups.get(v);const date=rows.map(r=>r.date).sort()[0];return `<section class="rule-section"><h2>Update ${esc(v)} <span class="objective-note">${esc(date)}</span></h2><ul class="check-list">${rows.map(e=>`<li>${e.link}: ${esc(e.change)} <span class="objective-note">${esc(e.evidence.kind.replace('-',' '))}${e.evidence.url?` · <a href="${esc(e.evidence.url)}">link</a>`:''}</span></li>`).join('')}</ul></section>`}).join('')||'<p>No dated changes have been recorded yet.</p>'}</section>`}

