function needSatisfiers(unitKey){return uniq(D.resources.filter(r=>r.publicly_named&&r.need_units[unitKey]>0)).sort((a,b)=>b.need_units[unitKey]-a.need_units[unitKey]||a.name.localeCompare(b.name))}
const NEED_RECORD={Food:'Food',Hydration:'Hydration',Heat:'Heat','Energy (sleep)':'Energy',Fun:'Entertainment',Cooling:'Refreshment',Wellness:'Wellness',Community:'Community'};
function needRecord(label){return (DM?.needs?.records||[]).find(x=>x.need===NEED_RECORD[label])||null}
function needSummaryRow(label){const rec=needRecord(label),unitKey=Object.values(NEED_UNITS).find(x=>x[1]===label)?.[0],items=unitKey?needSatisfiers(unitKey):[],places=placesFor(label),gear=statedFor(label).filter(e=>e.kind==='gear'&&e.item);const what={Food:'Hunger. Falls fastest and kills at −100.',Hydration:'Thirst, only in the Drylands. Kills.',Heat:'Warmth, only in the Winterlands. Kills.','Energy (sleep)':'Tiredness. Restored by sleeping in a house.',Fun:'Entertainment.',Cooling:'Relief from the heat, only in the Tropiclands.',Wellness:'Exercise and calm.',Community:'Company: eating together, gathering places.'}[label]||'';const by=[items.length?`${items.length} item${items.length===1?'':'s'}`:'',places.length?`${places.length} place${places.length===1?'':'s'}`:'',gear.length?`${gear.length} gear item${gear.length===1?'':'s'}`:'',label==='Energy (sleep)'?'sleep':''].filter(Boolean).join(', ');return `<tr><td><a href="#need-${slug(label)}">${esc(label)}</a></td><td>${esc(what)}</td><td>${rec?fmt(rec.DailyRequired):'—'}</td><td>${rec?fmt(rec.UnitValue):'—'}</td><td>${rec?.HasDeathValue?`yes, at ${fmt(rec.DeathValue)}`:'no'}</td><td>${by||'—'}</td></tr>`}
