function needsPage(){const hazard={Heat:'Winter',Cooling:'Tropical',Hydration:'Desert'};const labels=D.needs.map(n=>(NEED_UNITS[n.name]||[null,n.name])[1]);
 const overview=`<section class="rule-section" id="needs-overview"><h2>The eight needs at a glance</h2><p>Every need is a meter. It falls by a set amount each day and is topped up by eating or drinking something, visiting a place, wearing gear, or sleeping. Three of them kill when they run out. The numbers are the stored settings; nobody has timed them in play.</p><div class="table-wrap"><table><thead><tr><th scope="col">Need</th><th scope="col">What it is</th><th scope="col">Falls per day</th><th scope="col">One unit restores</th><th scope="col">Can kill</th><th scope="col">Restored by</th></tr></thead><tbody>${labels.map(needSummaryRow).join('')}</tbody></table></div><p class="small">Meter points = units × what one unit restores for that need. A 2-unit Bread is 120 points on a Food meter that falls 40 a day; a 1.2-unit plaza visit is 30 points on a Community meter that falls 20 a day.</p></section>`;
 const sections=D.needs.map(n=>{const [unitKey,label,concern]=NEED_UNITS[n.name]||[null,n.name,null];const items=unitKey?needSatisfiers(unitKey):[];const levels=concern?W.levels.filter(l=>l.scenario?.level_config?.[0]?.[concern]===true).length:null;const biome=hazard[label]?W.biomes.find(b=>b.id===hazard[label]):null;const text=biome?biomeRule(biome)?.special_needs_and_hazards?.[0]?.text:null;
  return `<section class="rule-section" id="need-${slug(label)}"><h2>${esc(label)}</h2>${text?`<div class="prose"><p>${rich(text)}</p></div>`:''}${items.length?`<h3>Items</h3>${needItemsTable(label,unitKey,items)}`:unitKey?'<p>No stored item carries units for this need.</p>':'<p>Restored by sleeping in a house. No item carries units for it; a villager with nowhere to sleep rests where they stand.</p>'}${unitKey?placesSection(label):''}${unitKey?statedSection(label):''}${levels!==null?`<p class="objective-note">Switched on in ${levels} of ${W.levels.length} levels; older maps may not record the setting.</p>`:''}</section>`}).join('');
 return `${header('Needs','What each villager need is, how fast it falls, and everything that restores it: items with their stored units, gathering places, gear and sleep. Stored settings read as named; the in-game test protocols are in the repository.','MECHANICS')}${overview}${needModelSection()}${eatingSection()}${sections}${villagerLifeSection()}${concernEffectsSection()}<section class="rule-section" id="need-housing"><h2>Housing</h2><p>Housing is a need switch on levels but has no resource; it is met by houses. The <a href="${url('houses')}">Houses</a> page compares every house: villager spots, crib and doghouse, cost per villager and where each can be built, and explains why spare houses keep births going.</p></section>`}
