function placementRow(b){const p=b.placement_rules;if(!p||b.is_plant)return null;const t=p.ValidTerrains||[];const names=t.map(terrainName).map(x=>x.toLowerCase());const terrain=t.length===0?'at the water’s edge (no land terrain listed)':t.length===1&&t[0]===3?'soil':names.join(', ').replace(/, ([^,]*)$/,' or $1');const h=p.MaxAllowedHeightDifference;const slope=h>=1000?'any slope':h>0.2?`slopes up to ${fmt(h)}`:'flat ground';const extra=[p.ConnectsZones?'connects zones':'',p.BuildOverWithBuildSite?'can be laid over build sites':''].filter(Boolean).join(', ');return `${terrain==='soil'&&slope==='flat ground'?'flat soil only':terrain+', '+slope}${extra?', '+extra:''}`}

// Tournament Mode: built from the game's own FastMode text (FastMode.Name resolves to “Tournament”). Seasons are withheld from the public page when the spoiler policy lists them.
function tournamentText(key){return (fullWorld||W).challenges.source_entries.find(e=>e.key===key)?.english||''}
function tText(s){let t=String(s||'');t=t.replace(/\[select value="\{[^}]+\}"\s+1="[^"]*"\s+2="([^"]*)"\]/g,'$1').replace(/\{count\}/g,'N').replace(/\{days\}/g,'N').replace(/\{points\}/g,'N').replace(/<sprite name=[^>]*>/g,'').replace(/\[\{seasonstyle\}\]|\[\{seasonStyle\}\]/gi,'the season’s').replace(/\[FastMode\.Props\.Banner\.Name\]/g,tournamentText('FastMode.Props.Banner.Name')||'Tournament Banner').replace(/\[Concern\.([A-Za-z]+)\.Name\]/g,(_,k)=>k==='Nutrition'?'Food':k==='Entertainment'?'Fun':k==='Refreshment'?'Cooling':k).replace(/\{Concern\.([A-Za-z]+)\.WithIcon\}/g,(_,k)=>k==='Nutrition'?'Food':k==='Entertainment'?'Fun':k==='Refreshment'?'Cooling':k).replace(/\{UI\.Boost\.([A-Za-z]+)\.WithIcon\}/g,'$1 Boost').replace(/\s+/g,' ').trim();return rich(t)}
function tournamentSeasons(){const entries=(fullWorld||W).challenges.source_entries;const ids=[...new Set(entries.filter(e=>/^FastMode\.[A-Za-z]+\.Name\.WithArticle$/.test(e.key)).map(e=>e.key.split('.')[1]))];return ids.map(id=>{const name=tournamentText(`FastMode.${id}.Name`)||id;const rewards=entries.filter(e=>e.key.startsWith(`FastMode.${id}.Reward.`)&&/\.Title$/.test(e.key)).map(e=>({n:+e.key.split('.')[3],title:e.english,description:tournamentText(e.key.replace(/Title$/,'Description'))})).sort((a,b)=>a.n-b.n);return {id,name,rewards,entries:entries.filter(e=>e.key.startsWith(`FastMode.${id}.`)).length,spoiler:spoilerEntry('tournament',id)}})}
function tournamentPage(showAll=false){return tournamentPageInner(showAll).replace(/<details open class="source"/g,'<details class="source"')}
function tournamentPageInner(showAll=false){const obs=(fullWorld||W).contributions?.filter(x=>x.target.type==='tournament')||[];const live=obs.find(x=>/live|current|running/i.test(x.claim)&&x.status==='confirmed');const seasons=tournamentSeasons().map(s=>({...s,current:!!(live&&live.target.id===s.id)})).sort((a,b)=>(b.current?1:0)-(a.current?1:0)),visible=seasons.filter(s=>showAll||!s.spoiler),withheld=seasons.filter(s=>s.spoiler);const T=tournamentText;const entries=(fullWorld||W).challenges.source_entries;
 const actions=entries.filter(e=>/^FastMode\.Action\.[A-Za-z.]+\.Name$/.test(e.key)).map(e=>({name:e.english,description:T(e.key.replace(/\.Name$/,'.Description'))}));
 const tutorials=W.levels.filter(l=>l.category==='tournament_tutorial').sort((a,b)=>a.id.localeCompare(b.id));
 const quote=keys=>`<ul class="check-list">${keys.map(k=>`<li>${tText(T(k))}</li>`).join('')}</ul>`;
 return `${showAll?`<aside class="notice"><div><strong>Spoilers: all Tournament seasons</strong><p>This view includes season styles withheld from the regular page because their release is unconfirmed.</p><a href="${url('spoilers')}">Spoiler index</a> · <a href="${url('tournament')}">Regular Tournament page</a></div></aside>`:''}${header('Tournament Mode','A daily, turn-based mode with its own levels, tiles, streaks, reward points and seasonal cosmetic styles, described in the game’s own words. The game files call it “FastMode”.','PLAY MODES')}<div class="tags">${tag('Recovered game text')}${live?tag(`Live · ${live.evidence.kind.replace('-',' ')} ${live.evidence.date}`):tag('Availability not checked on this installation','gray')}</div>
 <section class="rule-section"><h2>What it is</h2><div class="prose"><p>${tText(T('FastMode.LevelMenu.Description'))}</p><p>${tText(T('FastMode.Popup.TournamentIntro.Description'))}</p><p>${tText(T('FastMode.LevelInGame.Description'))}</p></div></section>
 <section class="rule-section"><h2>How a level plays</h2><p>From the Tournament Tutorial, in the game’s words:</p>${quote(['FastMode.Tutorial.Level1.Shared.Actions.1','FastMode.Tutorial.Level1.Shared.Bag.4','FastMode.Tutorial.Level1.Shared.Bag.5','FastMode.Tutorial.Level1.Shared.Skip.1','FastMode.Tutorial.Level1.Shared.Skip.2','FastMode.Tutorial.Level1.Shared.Skip.3'])}${tutorials.length?`<p>Tutorial levels: ${tutorials.map(l=>`<a href="${url('levels',l.id)}">${esc(l.name)}</a>`).join(', ')}.</p>`:''}</section>
 <section class="rule-section"><h2>Tiles</h2><p>The tiles a level can draw. Durations and counts are set per tile; the text shows the plural form.</p><div class="table-wrap"><table><thead><tr><th scope="col">Tile</th><th scope="col">Effect</th></tr></thead><tbody>${actions.map(a=>`<tr><td>${tText(a.name)}</td><td>${tText(a.description)}</td></tr>`).join('')}</tbody></table></div></section>
 <section class="rule-section"><h2>Reward Points, streaks and leaderboards</h2>${quote(['FastMode.RewardPoint.Description','FastMode.Level.MainObjectives.Description','FastMode.Level.OptionalObjectives.Description','FastMode.Streak.Inactive.Description','FastMode.Popup.Reward.StreakShield.Description','FastMode.UI.Leaderboards.TodayDescription','FastMode.UI.Leaderboards.OtherDayDescription'])}</section>
 <section class="rule-section"><h2>Seasons and styles</h2><p>${tText(T('FastMode.NewSeason.WelcomeDescription'))}</p>${visible.map(s=>`<h3>${esc(s.name)}${s.current?' '+tag(`Current season · reported ${esc(live.evidence.date)}`):''}${s.spoiler?' '+tag('Release unconfirmed','amber'):''}</h3>${s.current&&!s.rewards.length?`<p class="small">The live season’s reward set is not in the extracted text; completed seasons keep theirs in the files.</p>`:''}${s.rewards.length?`<ol class="story-levels">${s.rewards.map(r=>`<li>${tText(r.title)}${r.description?` <span class="objective-note">${tText(r.description)}</span>`:''}</li>`).join('')}</ol>`:s.current?'':`<p class="small">Only the style name is stored; no reward set.</p>`}`).join('')}${!showAll&&withheld.length?`<p class="small">${withheld.length} further season style${withheld.length>1?'s are':' is'} listed in the <a href="${url('spoilers')}">Spoilers</a> section because no release evidence exists for ${withheld.length>1?'them':'it'}.</p>`:''}</section>${boostsSection()}
 ${live?`<section class="rule-section"><h2>Observations</h2>${obs.map(x=>`<p><strong>${esc(x.claim)}</strong> <span class="objective-note">${esc(x.status)} · ${esc(x.evidence.kind.replace('-',' '))} · ${esc(x.evidence.date)}</span><br>${esc(x.notes||'')}</p>`).join('')}<p class="small">Seasons rotate; the wiki does not yet track their dates.</p></section>`:notice('Availability on this installation not checked','The menu observations of 24 October covered campaigns and the challenge archive, not Tournament Mode. Whether the mode, a current season, or either reward set is live has not been confirmed.')}${source({text_tables:['FastMode','FastSeasons','FastModeTutorial'],seasons:visible.map(s=>({id:s.id,name:s.name,text_entries:s.entries,reward_titles:s.rewards.length,release_unconfirmed:!!s.spoiler})),withheld_seasons:showAll?0:withheld.length},'Tournament text sources')}`}

// Need effects stated in the game's own building descriptions. Stored resource units miss dishes with a second effect, carried gear and places, so the descriptions are a second evidence source.
const CONCERN_LABEL={Nutrition:'Food',Food:'Food',Community:'Community',Entertainment:'Fun',Wellness:'Wellness',Heat:'Heat',Refreshment:'Cooling',Hydration:'Hydration'};
const CONCERN_UNIT={Food:'FoodUnits',Community:'CommunityUnits',Fun:'EntertainmentUnits',Wellness:'WellnessUnits',Heat:'HeatUnits',Cooling:'RefreshmentUnits',Hydration:'HydrationUnits'};
function statedEffects(){const out=[];for(const b of uniq(D.buildings.filter(b=>!isSuppressed('buildings',b.gameobject_id)&&b.description))){const concerns=[...new Set([...b.description.matchAll(/\{Concern\.([A-Za-z]+)\./g)].map(m=>CONCERN_LABEL[m[1]]).filter(Boolean))];if(!concerns.length)continue;
 const outputs=[...new Set(b.formula_ids.flatMap(i=>F[i]?.outputs.map(o=>o.resource_id)||[]))].map(id=>R[id]).filter(r=>r&&r.publicly_named);const gear=/carry around|equippable|wearer/i.test(b.description);
 for(const need of concerns){const unit=CONCERN_UNIT[need];const carriers=outputs.filter(r=>r.need_units[unit]>0);const item=outputs.find(r=>!gear?r.need_units.FoodUnits>0||r.need_units[unit]>0:true)||outputs[0]||null;
  out.push({need,building:b,item,kind:!outputs.length?'place':gear?'gear':'dish',stored:carriers.length>0})}}return out}
function statedFor(need){return statedEffects().filter(e=>e.need===need)}
function placesSection(need){const ps=placesFor(need);if(!ps.length)return '';const rec=needRecord(need);return `<h3>Places</h3><div class="table-wrap"><table><thead><tr><th scope="col">Place</th><th scope="col">Per visit</th><th scope="col">Meter points</th><th scope="col">Spots</th></tr></thead><tbody>${ps.map(b=>{const g=spotGroups(b).find(g=>g.units.some(u=>u.need===need)),u=g.units.find(u=>u.need===need);return `<tr><td>${icon('buildings',b)}<a href="${url('buildings',b.gameobject_id)}">${esc(b.name)}</a></td><td>${fmt(u.units)}</td><td>${rec?fmt(u.units*rec.UnitValue):'—'}</td><td>${fmt(spotsFor(b).length)}</td></tr>`}).join('')}</tbody></table></div><p class="small">Per-visit units stored on each building's social spots; the full table is on <a href="${url('gathering')}">Gathering places</a>.</p>`}
function statedSection(need){const rows=statedFor(need).filter(e=>!e.stored);if(!rows.length)return '';const group=kind=>rows.filter(e=>e.kind===kind);const amount=e=>{if(e.kind==='gear'&&e.item){const g=gearFor(e.item);if(g&&g.config?.BaseValueIncrease)return ` <span class="objective-note">base +${fmt(g.config.BaseValueIncrease)} (stored)</span>`}const v=socialNeedValue(e.building,e.need);return v!==null?` <span class="objective-note">${fmt(v)} (stored)</span>`:''};const link=e=>e.item?`<a href="${url('resources',e.item.id)}">${esc(e.item.name)}</a> <span class="objective-note">from the <a href="${url('buildings',e.building.gameobject_id)}">${esc(e.building.name)}</a></span>${amount(e)}`:`<a href="${url('buildings',e.building.gameobject_id)}">${esc(e.building.name)}</a>${amount(e)}`;
 const part=(title,xs)=>xs.length?`<p><strong>${title}:</strong> ${xs.map(link).join('; ')}</p>`:'';return `<div class="stated"><p class="objective-note">Also, according to the game’s building descriptions. Where a value is shown it is stored on the building’s social or eating spot, or on the gear item; how those values convert to the need meter is unverified. Dishes get their second effect when eaten at their building:</p>${part('Dishes',group('dish'))}${part('Carried gear',group('gear'))}${part('Places',group('place'))}</div>`}
function resourceStatedEffects(r){const vals=Object.fromEntries(Object.entries(r.need_units).filter(([,v])=>v));return statedEffects().filter(e=>e.item&&e.item.id===r.id&&!(vals[CONCERN_UNIT[e.need]]>0))}

// Research findings (content/reference/research-findings.json): decoded gear, social-spot, terrain and production-profile data handed over by the research agent. Rates are a supplied-inputs capacity model, never measured output.
function profileFor(b){const p=RF.profiles?.[b.gameobject_id];if(p)return p;const byName=Object.values(RF.profiles||{}).find(x=>x.name===b.name);return byName||null}
function gearFor(r){return (RF.gear_findings?.records||[]).find(g=>g.name===r.name)||null}
function socialFor(b){return (RF.social_spot_findings?.records||[]).filter(s=>{const target=B[s.building_id];return target&&target.name===b.name})}
function socialUnits(rec){const map={CommunityUnits:'Community',EntertainmentUnits:'Fun',WellnessUnits:'Wellness',HeatUnits:'Heat',RefreshmentUnits:'Cooling',HydrationUnits:'Hydration'};return Object.entries(rec.config||{}).filter(([k,v])=>map[k]&&v>0).map(([k,v])=>({need:map[k],units:+v.toFixed(2)}))}
const SPOT_NEED={community:'Community',entertainment:'Fun',wellness:'Wellness',heat:'Heat',refreshment:'Cooling',hydration:'Hydration'};
function spotsFor(b){const recs=DM?.social_spots?.records||{};for(const v of [b,...(b.variants||[])])if(recs[v.internal_name]?.length)return recs[v.internal_name];return []}
function spotGroups(b){const groups=new Map();for(const sp of spotsFor(b)){const units=Object.entries(sp.units).filter(([k,v])=>SPOT_NEED[k]&&v>0).map(([k,v])=>({need:SPOT_NEED[k],units:v}));const key=JSON.stringify([units,sp.duration,sp.choosable_for_community,sp.choosable_for_fun,sp.is_workspot]);if(!groups.has(key))groups.set(key,{units,duration:sp.duration,community:sp.choosable_for_community,fun:sp.choosable_for_fun,workspot:sp.is_workspot,count:0});groups.get(key).count++}return [...groups.values()]}
function unitsText(units){return units.length?units.map(u=>`${esc(u.need)} ${fmt(u.units)}`).join(', '):'no units on the spot itself'}
function gatheringRow(b){const gs=spotGroups(b);if(!gs.length||!gs.some(g=>g.units.length))return null;const n=gs.reduce((a,g)=>a+g.count,0);return `${plural(n,'spot')}: ${gs.map(g=>`${g.count<n?`${g.count} give `:'each visit gives '}${unitsText(g.units)}`).join('; ')} <span class="objective-note">(stored on its social spots; see <a href="${url('gathering')}">Gathering places</a>)</span>`}
function gatheringPage(){const bs=uniq(D.buildings.filter(b=>!b.is_plant&&!isSuppressed('buildings',b.gameobject_id)&&spotsFor(b).length)),types=DM?.social_spots?.spot_types||[],reuse=types.filter(t=>!t.path.startsWith('_')).map(t=>t.days_until_reuse),eating=DM?.social_spots?.eating_places||{};
 const rows=bs.map(b=>({b,gs:spotGroups(b),n:spotsFor(b).length})).sort((a,b)=>{const ua=Math.max(0,...a.gs.flatMap(g=>g.units.map(u=>u.units))),ub=Math.max(0,...b.gs.flatMap(g=>g.units.map(u=>u.units)));return ub-ua||a.b.name.localeCompare(b.b.name)}).map(({b,gs,n})=>{const eat=[b,...(b.variants||[])].map(v=>eating[v.internal_name]).find(Boolean);const counts=[...new Set(gs.flatMap(g=>[g.community?'Community':'',g.fun?'Fun':''].filter(Boolean)))];return `<tr><td>${icon('buildings',b)}<a href="${url('buildings',b.gameobject_id)}">${esc(b.name)}</a></td><td>${fmt(n)}</td><td>${gs.map(g=>`${gs.length>1?`${plural(g.count,g.workspot?'staff spot':'visitor spot')}: `:''}${unitsText(g.units)}${gs.length>1&&!g.workspot?' each':''}${g.workspot?' <span class="objective-note">(used by its own workers while on shift)</span>':''}`).join('<br>')}</td><td>${counts.length?counts.join(' or '):'—'}</td><td>${[...new Set(gs.map(g=>fmt(Math.round(g.duration*10)/10)))].join(' / ')}</td><td>${eat?`Serves food or drink from ${plural(eat.food_piles,'pile')}`:'—'}</td></tr>`}).join('');
 return `${header('Gathering places','The game says only that villagers “like to gather” at parks, plazas, kitchens and pubs. The files say what a visit is worth: each place has a number of spots, and each spot carries the Community, Fun, Wellness, Heat or Cooling units a villager gains from one use. These are stored settings; how a unit moves the meter and how often villagers drop by are not yet measured.','MECHANICS')}<div class="table-wrap"><table><thead><tr><th scope="col">Place</th><th scope="col">Spots</th><th scope="col">One visit gives</th><th scope="col">Can be picked when seeking</th><th scope="col">Visit length (raw)</th><th scope="col">Eating place</th></tr></thead><tbody>${rows}</tbody></table></div><section class="rule-section"><h2>How to read it</h2><p><strong>Spots</strong> are how many villagers can use the place at once. <strong>One visit gives</strong> is what each villager gains per use; A unit here is the same unit as on a food or drink item: ${(()=>{const c=(DM?.needs?.records||[]).find(x=>x.need==='Community');return c?`for Community, Fun, Wellness and Cooling the meter falls ${fmt(c.DailyRequired)} a day and one unit restores ${fmt(c.UnitValue)} points, so a 1.2-unit plaza visit covers about a day and a half of decay and a 6-unit pier or park visit fills the meter`:'see the Needs page for each meter'})()} (assuming a spot's units convert like an item's, which the field names say and nobody has timed). See the <a href="${url('needs')}">Needs</a> page. <strong>Can be picked when seeking</strong> is a stored switch: a villager looking for Community or Fun may set out for the place. Eating spots are switched off for the need they themselves give (an Open Kitchen cannot be picked for Community, a Fondue Bar not for Fun): you go there to eat, and the bonus comes with the meal. Where a spot shows no units, the value sits elsewhere: the dish or drink carries the food units at pubs and cookhouses, and the Bonfire's warmth comes from its heat pile (see its Heating row).</p><p>Spots come in two moods: the files hold separate animations for using a spot alone and with company, and most spots name a neighbour. Community by its nature needs company, so a lone villager on a bench gains less than the table suggests; the exact rule is code.</p>${reuse.length?`<p>A villager cannot reuse the same spot straight away: the stored delay is ${fmt(Math.min(...reuse))}–${fmt(Math.max(...reuse))} of a day depending on the place.</p>`:''}<p class="small">From every social spot on each building prefab (${bs.length} buildings), their eating-place and spot-type settings. Visit length is the raw stored value, not days or seconds. Buildings not listed carry no social spots.</p></section>`}
function placesFor(need){return uniq(D.buildings.filter(b=>!b.is_plant&&!isSuppressed('buildings',b.gameobject_id)&&spotGroups(b).some(g=>g.units.some(u=>u.need===need))))}
function socialRow(b){const g=gatheringRow(b);if(g)return g;const recs=socialFor(b);if(!recs.length)return null;const parts=recs.flatMap(rec=>socialUnits(rec).map(u=>`${esc(u.need)} ${fmt(u.units)}${rec.class==='WorkspotCompleteModifyNeed'?' when a worker finishes tending it':''}`));return parts.length?`${[...new Set(parts)].join(', ')} <span class="objective-note">(stored on its ${recs.some(r=>r.class==='SocialSpotBehaviour')?'social spot':'workspot'}; how it converts to the need meter is unverified)</span>`:null}
function socialNeedValue(b,need){for(const rec of socialFor(b))for(const u of socialUnits(rec))if(u.need===need)return u.units;return null}
function terrainName(code){return RF.terrain_placement_findings?.values?.[String(code)]||`terrain ${code}`}
function gearRow(r){const g=gearFor(r);if(!g)return null;const c=g.config||{};const parts=[];if(g.need&&g.need!=='None')parts.push(`raises base ${esc(g.need==='Entertainment'?'Fun':g.need==='Refreshment'?'Cooling':g.need)} <span class="objective-note">(stored value ${fmt(c.BaseValueIncrease)}; how it applies is unverified)</span>`);if(c.WalkSpeedMultipliers?.Base)parts.push(`walk speed ×${fmt(+c.WalkSpeedMultipliers.Base.toFixed(2))}${c.WalkSpeedMultipliers.Road?`, ×${fmt(+c.WalkSpeedMultipliers.Road.toFixed(2))} on roads`:''}`);if(c.AdultsOnly)parts.push('adults only');return parts.length?parts.join(' · '):'no stored effect'}
const PLANT_GROUPS={crop:'Field crop',orchard:'Fruit tree',forestry:'Forestry tree',decorative:'Decorative'};
function plantGroup(b){if(/planter|tree pit|decorative/i.test(b.internal_name||'')||/^Decorative/.test(b.internal_name||''))return 'decorative';return plantKind(b)}
function spreadFor(b){const rec=plantRecord(b);if(!rec)return null;return (DM?.plant_spread?.records||[]).find(x=>x.path===rec.root)||null}
function spreadText(b){const sp=spreadFor(b);if(!sp||!sp.daily_reproduction_chance)return null;return `${fmt(Math.round(sp.daily_reproduction_chance*1000)/10)}% chance a day to seed a new ${plantKind(b)==='orchard'&&/bush/i.test(b.name)?'bush':'tree'} within ${plural(sp.max_reproduction_distance,'tile')}, never closer than ${plural(sp.min_distance_with_other_plants,'tile')} to another plant`}
function spreadRange(){const v=(DM?.plant_spread?.records||[]).map(x=>x.daily_reproduction_chance).filter(Boolean);if(!v.length)return null;const lo=Math.min(...v)*100,hi=Math.max(...v)*100;return lo===hi?`${fmt(lo)}%`:`${fmt(lo)}–${fmt(hi)}%`}
function regrowthNote(b){const cats=new Set(b.formula_ids.flatMap(i=>F[i]?.resource_source_category_ids||[]));if(!cats.has(300150)&&!cats.has(300155))return '';const r=spreadRange();return r?`<p class="small">Wild trees regrow on their own: each tree has a ${r} chance a day to seed another within 3 tiles, so a stand that is not clear-felled keeps itself going. See each tree’s Spreads row.</p>`:''}
function workspotEffectsNote(b){const recs=(DM?.workspot_effects?.records||[]).filter(x=>x.root===b.internal_name);if(!recs.length)return '';const out=[];const rnd=recs.filter(x=>x.kind==='random_output');if(rnd.length){const groups=new Map();for(const x of rnd){const k=`${x.min}–${x.max}`;groups.set(k,(groups.get(k)||0)+1)}const parts=[...groups].map(([k,n])=>`${k} at ${plural(n,'spot')}`);const mean=rnd.reduce((a,x)=>a+(x.min+x.max)/2,0)/rnd.length;const spots=rnd.length;out.push(`${plural(spots,'work spot')}. Each cycle lands a random catch: ${groups.size===1?`${[...groups.keys()][0]} at every spot`:parts.join(', ')}, so about ${fmt(Math.round(mean*100)/100)} per cycle per spot on average, and catches come unevenly by design.`)}for(const x of recs.filter(x=>x.kind==='modify_need_on_complete')){const u=Object.entries(x.units).map(([k,v])=>`${fmt(v)} ${esc(needLabel(k[0].toUpperCase()+k.slice(1)))}`).join(', ');out.push(`Finishing the “${esc(x.workspot.replace(/ Workspot$/,''))}” task also gives the worker ${u} units, so tending it warms the tender as well as the people around it.`)}return `<p class="small">${out.join(' ')} <span class="objective-note">(stored on the workspot; not timed in play)</span></p>`}
function plantRecord(b){const fp=DM?.field_plants?.records?.[b.internal_name];const root=fp?.plant;return root?{root,spots:fp.planting_spots,...(DM.plants?.records?.[root]||{})}:null}
function fellingInfo(b){const rec=plantRecord(b);if(!rec||plantKind(b)==='crop')return null;const h=(rec.harvest||[]).find(x=>x.outputs?.length);if(!h)return null;return {outputs:h.outputs.map(o=>({...o,r:R[o.resource_id]})).filter(o=>o.r),actions:h.work_iterations}}
function fellingText(b){const f=fellingInfo(b);if(!f||!f.outputs.length)return null;return `${f.outputs.map(o=>`${fmt(o.count)} <a href="${url('resources',o.r.id)}">${esc(o.r.name)}</a>`).join(' and ')} per tree when felled${f.actions?` <span class="objective-note">(${plural(f.actions,'chop')})</span>`:''}`}
function spawnersOf(b){const rec=plantRecord(b);if(!rec)return [];return (rec.spawners||[]).map(sp=>{const y=(sp.spawn_yield||[]).flatMap(x=>x.outputs||[]);const r=y.length?R[y[0].resource_id]:null;return {...sp,r,count:y.length?y[0].count:0,mean:(sp.min_days+sp.max_days)/2}}).filter(sp=>!(sp.r&&spoilerEntry('resources',sp.r.id)))}
function fruitSpawners(b){return spawnersOf(b).filter(sp=>sp.r&&sp.r.publicly_named)}
function fruitRate(sp){return sp.count/sp.mean}
function fruitText(b){const fs=fruitSpawners(b);if(!fs.length)return null;return fs.map(sp=>{const every=sp.min_days===sp.max_days?`every ${plural(sp.min_days,'day')}`:`every ${fmt(sp.min_days)}–${fmt(sp.max_days)} days`;return `${fmt(sp.count)} <a href="${url('resources',sp.r.id)}">${esc(sp.r.name)}</a> ${every}, at most ${sp.max_spawned} waiting to be picked`}).join('<br>')}
function rateText(b){const fs=fruitSpawners(b);if(!fs.length)return null;return fs.map(sp=>`about ${fmt(Math.round(fruitRate(sp)*100)/100)} <a href="${url('resources',sp.r.id)}">${esc(sp.r.name)}</a> a day while picked; a full tree holds ${sp.max_spawned} and fills in about ${fmt(Math.round(sp.max_spawned*sp.mean))} days`).join('<br>')}
function rateCell(b){const fs=fruitSpawners(b);if(!fs.length)return '—';return fs.map(sp=>`${fmt(Math.round(fruitRate(sp)*100)/100)} ${esc(sp.r.name)}/day <span class="objective-note">(holds ${sp.max_spawned}, full in ${fmt(Math.round(sp.max_spawned*sp.mean))} days)</span>`).join('<br>')}
function otherDropsText(b){const lines=[];for(const sp of spawnersOf(b).filter(sp=>!sp.r)){const every=sp.min_days===sp.max_days?`every ${plural(sp.min_days,'day')}`:`every ${fmt(sp.min_days)}–${fmt(sp.max_days)} days`;
  if(/stick/i.test(sp.name)){const st=D.resources.find(x=>x.name==='Stick'&&x.publicly_named);lines.push(`a <a href="${url('resources',st?.id)}">Stick</a> ${every}, up to ${sp.max_spawned} lying around`)}
  else if(/bush/i.test(sp.name))lines.push(`a new bush ${every}, up to ${sp.max_spawned} nearby`);
  else if(/burrow|otter/i.test(sp.name))lines.push(`an animal burrow for trappers ${every}`);}
 return lines.length?lines.join('<br>'):null}
function mainYield(b){const k=plantKind(b);if(k==='crop')return yieldRow(b);if(k==='orchard')return fruitText(b)||fellingText(b);return fellingText(b)||fruitText(b)}
function alsoYield(b){const k=plantKind(b),parts=[];if(k==='orchard'){const f=fellingText(b);if(f)parts.push(f)}else if(k==='forestry'){const f=fruitText(b);if(f)parts.push(f)}const o=otherDropsText(b);if(o)parts.push(o);return parts.length?parts.join('<br>'):null}
function dropsRow(b){const rec=plantRecord(b);if(!rec)return null;const lines=[];for(const sp of rec.spawners||[]){const y=(sp.spawn_yield||[]).flatMap(x=>x.outputs||[]);const r=y.length?R[y[0].resource_id]:null;if(r&&spoilerEntry('resources',r.id))continue;const every=sp.min_days===sp.max_days?`every ${plural(sp.min_days,'day')}`:`every ${fmt(sp.min_days)}–${fmt(sp.max_days)} days`;
  if(r)lines.push(`${fmt(y[0].count)} <a href="${url('resources',r.id)}">${esc(r.name)}</a> ${every}, at most ${sp.max_spawned} waiting to be picked`);
  else if(/stick/i.test(sp.name)){const st=D.resources.find(x=>x.name==='Stick'&&x.publicly_named);lines.push(`a <a href="${url('resources',st?.id)}">Stick</a> ${every}, up to ${sp.max_spawned} lying around`)}
  else if(/bush/i.test(sp.name))lines.push(`a new bush ${every}, up to ${sp.max_spawned} nearby`);
  else if(/burrow|otter/i.test(sp.name))lines.push(`an animal burrow for trappers ${every}`);}
 return lines.length?lines.join('<br>'):null}
function yieldRow(b){const p=profileFor(b);if(!p||!p.yield?.length)return fellingText(b);return p.yield.map(y=>`${fmt(y.count)} <a href="${url('resources',y.resource_id)}">${esc(R[y.resource_id]?.name||y.name)}</a> per full field`).join(', ')+(p.planting_positions?` <span class="objective-note">(${p.planting_positions} planting spot${p.planting_positions===1?'':'s'})</span>`:'')}
function reportedRateRow(b){const p=profileFor(b);const r=p?.reported_rate;if(!r)return null;return `up to ${fmt(r.count)} <a href="${url('resources',r.resource_id)}">${esc(R[r.resource_id]?.name||'')}</a> per ${r.days===1?'day':r.days+' days'} <span class="objective-note">(player report)</span>`}
function productionHighlights(b){const p=profileFor(b);if(!p?.highlights?.length)return '';return `<section class="rule-section"><h2>Production notes</h2><p class="objective-note">From decoded stage timings and a supplied-inputs model; ceilings, not measured output.</p><ul class="check-list">${p.highlights.map(h=>`<li>${esc(h)}</li>`).join('')}</ul></section>`}
function productionModelResearch(b){const p=profileFor(b);if(!p)return '';const rates=(p.products||[]).filter(x=>x.rates?.length);const blockers=(p.products||[]).flatMap(x=>x.blockers||[]);if(!rates.length&&!blockers.length&&!p.notes?.length)return '';
 return `<section class="rule-section"><h2>Modelled production capacity</h2><p>A game day is ${fmt(RF.seconds_per_day)} simulation seconds${p.workday_fraction?` and this building works ${fmt(Math.round(p.workday_fraction*100))}% of it`:''}. The model assumes all inputs delivered and output cleared, and excludes walking, handoffs and contention; it is a ceiling for comparison, not a measured yield.</p>${rates.map(pr=>`<div class="table-wrap"><table><thead><tr><th>Workers</th><th>Batches per day</th><th>Output per day</th><th>Limited by</th></tr></thead><tbody>${pr.rates.map(rt=>`<tr><td>${rt.workers}</td><td>${fmt(+rt.batches_per_day.toFixed(2))}</td><td>${rt.outputs_per_day.map(o=>`${fmt(+o.per_day.toFixed(1))} ${esc(o.name)}`).join(', ')}</td><td>${esc(rt.limiting_stage||'')}</td></tr>`).join('')}</tbody></table></div>`).join('')}${blockers.length?`<p class="small">No daily estimate: ${esc([...new Set(blockers)].join('; '))}.</p>`:''}${p.notes?.length?`<ul class="check-list">${p.notes.map(n=>`<li>${esc(n)}</li>`).join('')}</ul>`:''}${source({profile:p,provenance:RF.provenance},'Production profile')}</section>`}
